/* DAWAH X — ahmad, অধ্যায় 82 · খণ্ড 82 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][82]=[[16201,16201,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَبِيدَةَ بْنِ أَبِي رَائِطَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ الْمُزَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَصْحَابِي لَا تَتَّخِذُوهُمْ ‏ ‏غَرَضًا ‏ ‏بَعْدِي فَمَنْ أَحَبَّهُمْ فَبِحُبِّي أَحَبَّهُمْ وَمَنْ أَبْغَضَهُمْ فَبِبُغْضِي أَبْغَضَهُمْ وَمَنْ آذَاهُمْ فَقَدْ آذَانِي وَمَنْ آذَانِي فَقَدْ آذَى اللَّهَ وَمَنْ آذَى اللَّهَ أَوْشَكَ أَنْ يَأْخُذَهُ ‏","","",""],[16202,16202,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ الرَّازِيُّ ‏ ‏عَنِ ‏ ‏الرَّبِيعِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏أَوْ عَنْ غَيْرِهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ الْمُزَنِيِّ ‏ ‏قَالَ ‏ ‏أَنَا شَهِدْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ ‏ ‏نَهَى عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏وَأَنَا شَهِدْتُهُ حِينَ رَخَّصَ فِيهِ قَالَ وَاجْتَنِبُوا الْمُسْكِرَ ‏","","",""],[16203,16203,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ رَفِيقٌ يُحِبُّ الرِّفْقَ ‏ ‏وَيَرْضَاهُ وَيُعْطِي عَلَى الرِّفْقِ مَا لَا يُعْطِي عَلَى الْعُنْفِ ‏","","",""],[16204,16204,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏أَنَّ رَجُلًا لَقِيَ امْرَأَةً كَانَتْ ‏ ‏بَغِيًّا ‏ ‏فِي الْجَاهِلِيَّةِ فَجَعَلَ يُلَاعِبُهَا حَتَّى بَسَطَ يَدَهُ إِلَيْهَا فَقَالَتْ الْمَرْأَةُ ‏ ‏مَهْ ‏ ‏فَإِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ ذَهَبَ بِالشِّرْكِ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً ذَهَبَ بِالْجَاهِلِيَّةِ وَجَاءَنَا بِالْإِسْلَامِ ‏ ‏فَوَلَّى الرَّجُلُ فَأَصَابَ وَجْهَهُ الْحَائِطُ ‏ ‏فَشَجَّهُ ‏ ‏ثُمَّ أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ فَقَالَ ‏ ‏أَنْتَ عَبْدٌ أَرَادَ اللَّهُ بِكَ خَيْرًا إِذَا أَرَادَ اللَّهُ عَزَّ وَجَلَّ بِعَبْدٍ خَيْرًا عَجَّلَ لَهُ عُقُوبَةَ ذَنْبِهِ وَإِذَا أَرَادَ بِعَبْدٍ شَرًّا أَمْسَكَ عَلَيْهِ بِذَنْبِهِ حَتَّى يُوَفَّى بِهِ يَوْمَ الْقِيَامَةِ كَأَنَّهُ ‏ ‏عَيْرٌ ‏","","",""],[16205,16205,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ثَابِتُ بْنُ يَزِيدَ أَبُو زَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏عَنْ ‏ ‏فُضَيْلِ بْنِ زَيْدٍ الرَّقَاشِيِّ ‏ ‏وَقَدْ غَزَا سَبْعَ غَزَوَاتٍ فِي إِمْرَةِ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏أَنَّهُ أَتَى ‏ ‏عَبْدَ اللَّهِ بْنَ مُغَفَّلٍ ‏ ‏فَقَالَ أَخْبِرْنِي بِمَا حَرَّمَ اللَّهُ عَلَيْنَا مِنْ هَذَا الشَّرَابِ فَقَالَ الْخَمْرَ قَالَ هَذَا فِي الْقُرْآنِ أَفَلَا أُحَدِّثُكَ سَمِعْتُ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَدَأَ ‏ ‏بِالِاسْمِ ‏ ‏أَوْ بِالرِّسَالَةِ ‏ ‏قَالَ شَرْعِي أَنِّي اكْتَفَيْتُ قَالَ ‏ ‏نَهَى عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَالنَّقِيرِ ‏ ‏وَالْمُقَيَّرِ ‏ ‏قَالَ ‏ ‏مَا ‏ ‏الْحَنْتَمُ ‏ ‏قَالَ ‏ ‏الْأَخْضَرُ وَالْأَبْيَضُ قَالَ مَا ‏ ‏الْمُقَيَّرُ ‏ ‏قَالَ مَا لُطِخَ ‏ ‏بِالْقَارِ ‏ ‏مِنْ ‏ ‏زِقٍّ ‏ ‏أَوْ غَيْرِهِ ‏ ‏قَالَ ‏ ‏فَانْطَلَقْتُ إِلَى السُّوقِ فَاشْتَرَيْتُ ‏ ‏أَفِيقَةً ‏ ‏فَمَا زَالَتْ مُعَلَّقَةً فِي بَيْتِي ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏فَحَدَّثَ رَجُلٌ عِنْدَهُ مِنْ قَوْمِهِ فَذَكَرَ الْحَدِيثَ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏أَخْطَأَ فِيهِ ‏ ‏مَعْمَرٌ ‏ ‏لِأَنَّ ‏ ‏سَعِيدَ بْنَ جُبَيْرٍ ‏ ‏لَمْ يَلْقَ ‏ ‏عَبْدَ اللَّهِ بْنَ مُغَفَّلٍ ‏","","",""],[16206,16206,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَزْهَرَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَخَلَّلُ ‏ ‏النَّاسَ يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏يَسْأَلُ عَنْ مَنْزِلِ ‏ ‏خَالِدِ بْنِ الْوَلِيدِ ‏ ‏فَأُتِيَ بِسَكْرَانَ ‏ ‏فَأَمَرَ مَنْ كَانَ مَعَهُ أَنْ يَضْرِبُوهُ بِمَا كَانَ فِي أَيْدِيهِمْ ‏","","",""],[16207,16207,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ أَزْهَرَ ‏ ‏يَقُولُ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَزَاةَ يَوْمِ الْفَتْحِ وَأَنَا غُلَامٌ شَابٌّ ‏ ‏يَتَخَلَّلُ ‏ ‏النَّاسَ يَسْأَلُ عَنْ مَنْزِلِ ‏ ‏خَالِدِ بْنِ الْوَلِيدِ ‏ ‏فَأُتِيَ بِشَارِبٍ فَأَمَرَهُمْ فَضَرَبُوهُ بِمَا فِي أَيْدِيهِمْ فَمِنْهُمْ مَنْ ضَرَبَهُ بِعَصًا وَمِنْهُمْ مَنْ ضَرَبَهُ بِسَوْطٍ وَحَثَى عَلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏التُّرَابَ ‏","","",""],[16208,16208,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ الْأَزْهَرِ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ ‏ ‏خَالِدَ بْنَ الْوَلِيدِ بْنِ الْمُغِيرَةِ ‏ ‏جُرِحَ يَوْمَئِذٍ وَكَانَ عَلَى الْخَيْلِ خَيْلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ابْنُ الْأَزْهَرِ ‏ ‏قَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَمَا هَزَمَ اللَّهُ الْكُفَّارَ وَرَجَعَ الْمُسْلِمُونَ إِلَى ‏ ‏رِحَالِهِمْ ‏ ‏يَمْشِي فِي الْمُسْلِمِينَ وَيَقُولُ ‏ ‏مَنْ يَدُلُّ عَلَى ‏ ‏رَحْلِ ‏ ‏خَالِدِ بْنِ الْوَلِيدِ ‏ ‏قَالَ فَمَشَيْتُ ‏ ‏أَوْ قَالَ فَسَعَيْتُ ‏ ‏بَيْنَ يَدَيْهِ وَأَنَا ‏ ‏مُحْتَلِمٌ ‏ ‏أَقُولُ مَنْ يَدُلُّ عَلَى ‏ ‏رَحْلِ ‏ ‏خَالِدٍ ‏ ‏حَتَّى حَلَلْنَا عَلَى ‏ ‏رَحْلِهِ ‏ ‏فَإِذَا ‏ ‏خَالِدُ بْنُ الْوَلِيدِ ‏ ‏مُسْتَنِدٌ إِلَى ‏ ‏مُؤْخِرَةِ رَحْلِهِ ‏ ‏فَأَتَاهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَظَرَ إِلَى جُرْحِهِ ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏وَحَسِبْتُ أَنَّهُ قَالَ ‏ ‏وَنَفَثَ ‏ ‏فِيهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏آخِرُ مُسْنَدِ ‏ ‏الْمَكِّيِّينَ ‏ ‏وَالْمَدَنِيِّينَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمْ ‏","","",""],[16209,16209,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ كَيْسَانَ ‏ ‏وَحَدَّثَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ بْنِ سَهْلٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّهُ أَخْبَرَهُ أَنَّ ‏ ‏خَالِدَ بْنَ الْوَلِيدِ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ دَخَلَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏مَيْمُونَةَ بِنْتِ الْحَارِثِ ‏ ‏وَهِيَ خَالَتُهُ فَقَدَّمَتْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَحْمَ ضَبٍّ جَاءَتْ بِهِ ‏ ‏أُمُّ حُفَيْدٍ بِنْتُ الْحَارِثِ ‏ ‏مِنْ ‏ ‏نَجْدٍ ‏ ‏وَكَانَتْ تَحْتَ رَجُلٍ مِنْ ‏ ‏بَنِي جَعْفَرٍ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَأْكُلُ شَيْئًا حَتَّى يَعْلَمَ مَا هُوَ فَقَالَ بَعْضُ النِّسْوَةِ ‏ ‏أَلَا تُخْبِرْنَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا يَأْكُلُ فَأَخْبَرْنَهُ أَنَّهُ لَحْمُ ضَبٍّ فَتَرَكَهُ فَقَالَ ‏ ‏خَالِدٌ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَرَامٌ هُوَ قَالَ لَا وَلَكِنَّهُ طَعَامٌ لَيْسَ فِي قَوْمِي فَأَجِدُنِي ‏ ‏أَعَافُهُ ‏ ‏قَالَ ‏ ‏خَالِدٌ ‏ ‏فَاجْتَرَرْتُهُ ‏ ‏إِلَيَّ فَأَكَلْتُهُ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْظُرُ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏وَحَدَّثَهُ ‏ ‏الْأَصَمُّ يَعْنِي يَزِيدَ بْنَ الْأَصَمِّ ‏ ‏عَنْ ‏ ‏مَيْمُونَةَ ‏ ‏وَكَانَ فِي ‏ ‏حَجْرِهَا ‏","","",""],[16210,16210,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ بْنِ سَهْلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏وَخَالِدِ بْنِ الْوَلِيدِ ‏ ‏أَنَّهُمَا دَخَلَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْتَ ‏ ‏مَيْمُونَةَ ‏ ‏فَأُتِيَ بِضَبٍّ ‏ ‏مَحْنُوذٍ ‏ ‏فَأَهْوَى ‏ ‏إِلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ بَعْضُ النِّسْوَةِ أَخْبِرُوا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا يُرِيدُ أَنْ يَأْكُلَ فَقَالُوا ‏ ‏هُوَ ضَبٌّ يَا رَسُولَ اللَّهِ فَرَفَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَهُ فَقُلْتُ أَحَرَامٌ هُوَ يَا رَسُولَ اللَّهِ قَالَ لَا وَلَكِنْ لَمْ يَكُنْ بِأَرْضِ قَوْمِي فَأَجِدُنِي ‏ ‏أَعَافُهُ ‏ ‏قَالَ ‏ ‏خَالِدٌ ‏ ‏فَاجْتَرَرْتُهُ ‏ ‏فَأَكَلْتُهُ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْظُرُ ‏","","",""],[16211,16211,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْعَوَّامُ بْنُ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ الْوَلِيدِ ‏ ‏قَالَ ‏ ‏كَانَ بَيْنِي وَبَيْنَ ‏ ‏عَمَّارِ بْنِ يَاسِرٍ ‏ ‏كَلَامٌ ‏ ‏فَأَغْلَظْتُ ‏ ‏لَهُ فِي الْقَوْلِ فَانْطَلَقَ ‏ ‏عَمَّارٌ ‏ ‏يَشْكُونِي إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَاءَ ‏ ‏خَالِدٌ ‏ ‏وَهُوَ ‏ ‏يَشْكُوهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَجَعَلَ ‏ ‏يُغْلِظُ ‏ ‏لَهُ وَلَا يَزِيدُ إِلَّا ‏ ‏غِلْظَةً ‏ ‏وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَاكِتٌ لَا يَتَكَلَّمُ فَبَكَى ‏ ‏عَمَّارٌ ‏ ‏وَقَالَ يَا رَسُولَ اللَّهِ أَلَا تَرَاهُ فَرَفَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأْسَهُ قَالَ ‏ ‏مَنْ عَادَى ‏ ‏عَمَّارًا ‏ ‏عَادَاهُ اللَّهُ وَمَنْ أَبْغَضَ ‏ ‏عَمَّارًا ‏ ‏أَبْغَضَهُ اللَّهُ ‏ ‏قَالَ ‏ ‏خَالِدٌ ‏ ‏فَخَرَجْتُ فَمَا كَانَ شَيْءٌ أَحَبَّ إِلَيَّ مِنْ رِضَا ‏ ‏عَمَّارٍ ‏ ‏فَلَقِيتُهُ فَرَضِيَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏سَمِعْتُهُ مِنْ أَبِي مَرَّتَيْنِ ‏","","",""],[16212,16212,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو أُمَامَةَ بْنُ سَهْلِ بْنِ حُنَيْفٍ الْأَنْصَارِيُّ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏خَالِدَ بْنَ الْوَلِيدِ ‏ ‏الَّذِي يُقَالُ لَهُ سَيْفُ اللَّهِ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ دَخَلَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهِيَ خَالَتُهُ وَخَالَةُ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏فَوَجَدَ عِنْدَهَا ضَبًّا ‏ ‏مَحْنُوذًا ‏ ‏قَدِمَتْ بِهِ أُخْتُهَا ‏ ‏حُفَيْدَةُ بِنْتُ الْحَارِثِ ‏ ‏مِنْ ‏ ‏نَجْدٍ ‏ ‏فَقَدَّمَتْ الضَّبَّ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ قَلَّمَا يُقَدِّمُ يَدَهُ لِطَعَامٍ حَتَّى يُحَدَّثَ بِهِ وَيُسَمَّى لَهُ فَأَهْوَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَهُ إِلَى الضَّبِّ فَقَالَتْ امْرَأَةٌ مِنْ النِّسْوَةِ الْحُضُورِ أَخْبِرْنَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا قَدَّمْتُنَّ إِلَيْهِ قُلْنَ هُوَ الضَّبُّ يَا رَسُولَ اللَّهِ فَرَفَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَهُ عَنْ الضَّبِّ فَقَالَ ‏ ‏خَالِدُ بْنُ الْوَلِيدِ ‏ ‏أَحَرَامٌ الضَّبُّ يَا رَسُولَ اللَّهِ قَالَ لَا وَلَكِنْ لَمْ يَكُنْ بِأَرْضِ قَوْمِي فَأَجِدُنِي ‏ ‏أَعَافُهُ ‏ ‏قَالَ ‏ ‏خَالِدٌ ‏ ‏فَاجْتَرَرْتُهُ ‏ ‏فَأَكَلْتُهُ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْظُرُ إِلَيَّ فَلَمْ يَنْهَنِي ‏","","",""],[16213,16213,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ حَرْبٍ يَعْنِي الْأَبْرَشَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ سُلَيْمٍ أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏صَالِحٍ يَعْنِي ابْنَ يَحْيَى بْنِ الْمِقْدَامِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ ‏ ‏قَالَ ‏ ‏غَزَوْنَا مَعَ ‏ ‏خَالِدِ بْنِ الْوَلِيدِ ‏ ‏الصَّائِفَةَ ‏ ‏فَقَرِمَ ‏ ‏أَصْحَابُنَا إِلَى اللَّحْمِ فَسَأَلُونِي فَقَالُوا أَتَأْذَنُ لَنَا أَنْ نَذْبَحَ ‏ ‏رَمْكَةً ‏ ‏لَهُ فَدَفَعْتُهَا إِلَيْهِمْ فَحَبَلُوهَا ثُمَّ قُلْتُ مَكَانَكُمْ حَتَّى آتِيَ ‏ ‏خَالِدًا ‏ ‏فَأَسْأَلَهُ قَالَ فَأَتَيْتُهُ فَسَأَلْتُهُ فَقَالَ غَزَوْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَزْوَةَ ‏ ‏خَيْبَرَ ‏ ‏فَأَسْرَعَ النَّاسُ فِي حَظَائِرِ ‏ ‏يَهُودَ ‏ ‏فَأَمَرَنِي أَنْ أُنَادِيَ الصَّلَاةُ جَامِعَةٌ وَلَا يَدْخُلُ الْجَنَّةَ إِلَّا مُسْلِمٌ ثُمَّ قَالَ أَيُّهَا النَّاسُ إِنَّكُمْ قَدْ أَسْرَعْتُمْ فِي حَظَائِرِ ‏ ‏يَهُودَ ‏ ‏أَلَا ‏ ‏لَا تَحِلُّ أَمْوَالُ الْمُعَاهَدِينَ إِلَّا بِحَقِّهَا وَحَرَامٌ عَلَيْكُمْ لُحُومُ الْحُمُرِ الْأَهْلِيَّةِ وَخَيْلِهَا وَبِغَالِهَا وَكُلِّ ذِي ‏ ‏نَابٍ مِنْ السِّبَاعِ وَكُلِّ ذِي مِخْلَبٍ مِنْ الطَّيْرِ ‏","","",""],[16214,16214,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ رَبِّهِ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنِي ‏ ‏ثَوْرُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ يَحْيَى بْنِ الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ الْوَلِيدِ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ أَكْلِ لُحُومِ الْخَيْلِ وَالْبِغَالِ وَالْحَمِيرِ ‏","","",""],[16215,16215,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ حَرْبٍ الْخَوْلَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْحِمْصِيُّ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ يَحْيَى بْنِ الْمِقْدَامِ ‏ ‏عَنِ ‏ ‏ابْنِ الْمِقْدَامِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏الْمِقْدَامِ بْنِ مَعْدِي كَرِبَ ‏ ‏قَالَ ‏ ‏غَزَوْتُ مَعَ ‏ ‏خَالِدِ بْنِ الْوَلِيدِ ‏ ‏الصَّائِفَةَ ‏ ‏فَقَرِمَ ‏ ‏أَصْحَابِي إِلَى اللَّحْمِ فَقَالُوا أَتَأْذَنُ لَنَا أَنْ نَذْبَحَ ‏ ‏رَمْكَةً ‏ ‏لَهُ قَالَ فَحَبَلُوهَا فَقُلْتُ مَكَانَكُمْ حَتَّى آتِيَ ‏ ‏خَالِدَ بْنَ الْوَلِيدِ ‏ ‏فَأَسْأَلَهُ عَنْ ذَلِكَ فَأَتَيْتُهُ فَأَخْبَرْتُهُ خَبَرَ أَصْحَابِي فَقَالَ غَزَوْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَزْوَةَ ‏ ‏خَيْبَرَ ‏ ‏فَأَسْرَعَ النَّاسُ فِي ‏ ‏حَظَائِرِ ‏ ‏يَهُودَ ‏ ‏فَقَالَ يَا ‏ ‏خَالِدُ ‏ ‏نَادِ فِي النَّاسِ أَنَّ الصَّلَاةَ جَامِعَةٌ لَا يَدْخُلُ الْجَنَّةَ إِلَّا مُسْلِمٌ فَفَعَلْتُ فَقَامَ فِي النَّاسِ فَقَالَ يَا أَيُّهَا النَّاسُ مَا بَالُكُمْ أَسْرَعْتُمْ فِي حَظَائِرِ ‏ ‏يَهُودَ ‏ ‏أَلَا ‏ ‏لَا تَحِلُّ أَمْوَالُ الْمُعَاهَدِينَ إِلَّا بِحَقِّهَا وَحَرَامٌ عَلَيْكُمْ حُمُرُ الْأَهْلِيَّةِ وَالْإِنْسِيَّةِ وَخَيْلُهَا وَبِغَالُهَا وَكُلُّ ذِي ‏ ‏نَابٍ مِنْ السِّبَاعِ وَكُلُّ ذِي مِخْلَبٍ مِنْ الطَّيْرِ ‏","","",""],[16216,16216,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنِ ‏ ‏أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ حَكِيمِ بْنِ حِزَامٍ ‏ ‏قَالَ ‏ ‏تَنَاوَلَ ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏رَجُلًا بِشَيْءٍ فَنَهَاهُ ‏ ‏خَالِدُ بْنُ الْوَلِيدِ ‏ ‏فَقَالَ أَغْضَبْتَ الْأَمِيرَ فَأَتَاهُ فَقَالَ إِنِّي لَمْ أُرِدْ أَنْ أُغْضِبَكَ وَلَكِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ أَشَدَّ النَّاسِ عَذَابًا يَوْمَ الْقِيَامَةِ أَشَدُّ النَّاسِ عَذَابًا لِلنَّاسِ فِي الدُّنْيَا ‏","","",""],[16217,16217,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏عَزْرَةَ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بنِ الْوَلِيدِ ‏ ‏قَالَ ‏ ‏كَتَبَ إِلَيَّ أَمِيرُ الْمُؤْمِنِينَ حِينَ أَلْقَى ‏ ‏الشَّامَ ‏ ‏بَوَانِيَةً ‏ ‏بَثْنِيَةً ‏ ‏وَعَسَلًا ‏ ‏وَشَكَّ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً قَالَ حِينَ أَلْقَى ‏ ‏الشَّامَ ‏ ‏كَذَا وَكَذَا ‏ ‏فَأَمَرَنِي أَنْ أَسِيرَ إِلَى ‏ ‏الْهِنْدِ ‏ ‏وَالْهِنْدُ ‏ ‏فِي أَنْفُسِنَا يَوْمَئِذٍ ‏ ‏الْبَصْرَةُ ‏ ‏قَالَ وَأَنَا لِذَلِكَ كَارِهٌ قَالَ فَقَامَ رَجُلٌ فَقَالَ لِي يَا ‏ ‏أَبَا سُلَيْمَانَ ‏ ‏اتَّقِ اللَّهَ فَإِنَّ ‏ ‏الْفِتَنَ ‏ ‏قَدْ ظَهَرَتْ قَالَ فَقَالَ ‏ ‏وَابْنُ الْخَطَّابِ ‏ ‏حَيٌّ إِنَّمَا تَكُونُ بَعْدَهُ وَالنَّاسُ ‏ ‏بِذِي بِلِّيَانَ ‏ ‏وَذِي بِلِّيَانَ ‏ ‏بِمَكَانِ كَذَا وَكَذَا فَيَنْظُرُ الرَّجُلُ فَيَتَفَكَّرُ هَلْ يَجِدُ مَكَانًا لَمْ يَنْزِلْ بِهِ مِثْلُ مَا نَزَلَ بِمَكَانِهِ الَّذِي هُوَ فِيهِ مِنْ ‏ ‏الْفِتْنَةِ ‏ ‏وَالشَّرِّ فَلَا يَجِدُهُ قَالَ وَتِلْكَ الْأَيَّامُ الَّتِي ذَكَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ يَدَيْ السَّاعَةِ أَيَّامُ ‏ ‏الْهَرْجِ ‏ ‏فَنَعُوذُ بِاللَّهِ أَنْ تُدْرِكَنَا وَإِيَّاكُمْ تِلْكَ الْأَيَّامُ ‏","","",""],[16218,16218,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْأَشْتَرِ ‏ ‏قَالَ ‏ ‏كَانَ بَيْنَ ‏ ‏عَمَّارٍ ‏ ‏وَبَيْنَ ‏ ‏خَالِدِ بْنِ الْوَلِيدِ ‏ ‏كَلَامٌ فَشَكَاهُ ‏ ‏عَمَّارٌ ‏ ‏إِلَى رَسُولِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ مَنْ يُعَادِ ‏ ‏عَمَّارًا ‏ ‏يُعَادِهِ اللَّهُ عَزَّ وَجَلَّ وَمَنْ يُبْغِضْهُ يُبْغِضْهُ اللَّهُ عَزَّ وَجَلَّ وَمَنْ يَسُبَّهُ يَسُبَّهُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏فَقَالَ ‏ ‏سَلَمَةُ ‏ ‏هَذَا أَوْ ‏ ‏نَحْوَهُ ‏","","",""],[16219,16219,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ ‏ ‏وَخَالِدِ بْنِ الْوَلِيدِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ ‏ ‏يُخَمِّسْ ‏ ‏السَّلَبَ ‏","","",""],[16220,16220,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ الْجُعْفِيُّ ‏ ‏عَنْ ‏ ‏زَائِدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏قَالَ ‏ ‏اسْتَعْمَلَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏أَبَا عُبَيْدَةَ بْنَ الْجَرَّاحِ ‏ ‏عَلَى ‏ ‏الشَّامِ ‏ ‏وَعَزَلَ ‏ ‏خَالِدَ بْنَ الْوَلِيدِ ‏ ‏قَالَ فَقَالَ ‏ ‏خَالِدُ بْنُ الْوَلِيدِ ‏ ‏بُعِثَ عَلَيْكُمْ أَمِينُ هَذِهِ الْأُمَّةِ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَمِينُ هَذِهِ الْأُمَّةِ ‏ ‏أَبُو عُبَيْدةَ بْنُ الْجَرَّاحِ ‏ ‏قَالَ ‏ ‏أَبُو عُبَيْدَةَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏خَالِدٌ ‏ ‏سَيْفٌ مِنْ سُيُوفِ اللَّهِ عَزَّ وَجَلَّ وَنِعْمَ فَتَى الْعَشِيرَةِ ‏","","",""],[16221,16221,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏حَرِيزٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ صُلَيْحٍ ‏ ‏عَنْ ‏ ‏ذِي مِخْمَرٍ ‏ ‏وَكَانَ رَجُلًا مِنْ ‏ ‏الْحَبَشَةِ ‏ ‏يَخْدُمُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَهُ فِي سَفَرٍ فَأَسْرَعَ السَّيْرَ حِينَ انْصَرَفَ وَكَانَ يَفْعَلُ ذَلِكَ لِقِلَّةِ الزَّادِ فَقَالَ لَهُ قَائِلٌ يَا رَسُولَ اللَّهِ قَدْ انْقَطَعَ النَّاسُ وَرَاءَكَ فَحَبَسَ وَحَبَسَ النَّاسُ مَعَهُ حَتَّى تَكَامَلُوا إِلَيْهِ فَقَالَ لَهُمْ هَلْ لَكُمْ أَنْ ‏ ‏نَهْجَعَ ‏ ‏هَجْعَةً ‏ ‏أَوْ قَالَ لَهُ قَائِلٌ ‏ ‏فَنَزَلَ وَنَزَلُوا فَقَالَ مَنْ ‏ ‏يَكْلَؤُنَا ‏ ‏اللَّيْلَةَ فَقُلْتُ أَنَا جَعَلَنِي اللَّهُ فِدَاءَكَ فَأَعْطَانِي ‏ ‏خِطَامَ ‏ ‏نَاقَتِهِ فَقَالَ ‏ ‏هَاكَ ‏ ‏لَا تَكُونُنَّ ‏ ‏لُكَعَ ‏ ‏قَالَ فَأَخَذْتُ ‏ ‏بِخِطَامِ ‏ ‏نَاقَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبِخِطَامِ نَاقَتِي فَتَنَحَّيْتُ غَيْرَ بَعِيدٍ فَخَلَّيْتُ سَبِيلَهُمَا يَرْعَيَانِ فَإِنِّي كَذَاكَ أَنْظُرُ إِلَيْهِمَا حَتَّى أَخَذَنِي النَّوْمُ فَلَمْ أَشْعُرْ بِشَيْءٍ حَتَّى وَجَدْتُ حَرَّ الشَّمْسِ عَلَى وَجْهِي فَاسْتَيْقَظْتُ فَنَظَرْتُ يَمِينًا وَشِمَالًا فَإِذَا أَنَا بِالرَّاحِلَتَيْنِ مِنِّي غَيْرُ بَعِيدٍ فَأَخَذْتُ ‏ ‏بِخِطَامِ ‏ ‏نَاقَةِ ‏ ‏النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبِخِطَامِ ‏ ‏نَاقَتِي فَأَتَيْتُ ‏ ‏أَدْنَى ‏ ‏الْقَوْمِ فَأَيْقَظْتُهُ فَقُلْتُ لَهُ أَصَلَّيْتُمْ قَالَ لَا فَأَيْقَظَ النَّاسُ بَعْضُهُمْ بَعْضًا حَتَّى اسْتَيْقَظَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا ‏ ‏بِلَالُ ‏ ‏هَلْ لِي فِي ‏ ‏الْمِيضَأَةِ ‏ ‏يَعْنِي الْإِدَاوَةَ ‏ ‏قَالَ نَعَمْ جَعَلَنِي اللَّهُ فِدَاءَكَ فَأَتَاهُ بِوَضُوءٍ فَتَوَضَّأَ لَمْ ‏ ‏يَلُتَّ ‏ ‏مِنْهُ التُّرَابَ فَأَمَرَ ‏ ‏بِلَالًا ‏ ‏فَأَذَّنَ ثُمَّ قَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى الرَّكْعَتَيْنِ قَبْلَ الصُّبْحِ وَهُوَ غَيْرُ ‏ ‏عَجِلٍ ‏ ‏ثُمَّ أَمَرَهُ فَأَقَامَ الصَّلَاةَ فَصَلَّى وَهُوَ غَيْرُ ‏ ‏عَجِلٍ ‏ ‏فَقَالَ لَهُ قَائِلٌ يَا نَبِيَّ اللَّهِ أَفْرَطْنَا قَالَ ‏ ‏لَا قَبَضَ اللَّهُ عَزَّ وَجَلَّ أَرْوَاحَنَا وَقَدْ رَدَّهَا إِلَيْنَا وَقَدْ صَلَّيْنَا ‏","","",""],[16222,16222,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏حَسَّانَ بْنِ عَطِيَّةَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏ذِي مِخْمَرٍ ‏ ‏رَجُلٍ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏سَتُصَالِحُكُمْ ‏ ‏الرُّومُ ‏ ‏صُلْحًا آمِنًا ثُمَّ تَغْزُونَ وَهُمْ عَدُوًّا فَتُنْصَرُونَ وَتَسْلَمُونَ وَتَغْنَمُونَ ثُمَّ تَنْصُرُونَ ‏ ‏الرُّومَ ‏ ‏حَتَّى تَنْزِلُوا ‏ ‏بِمَرْجٍ ‏ ‏ذِي تُلُولٍ ‏ ‏فَيَرْفَعُ رَجُلٌ مِنْ النَّصْرَانِيَّةِ صَلِيبًا فَيَقُولُ غَلَبَ الصَّلِيبُ فَيَغْضَبُ رَجُلٌ مِنْ الْمُسْلِمِينَ فَيَقُومُ إِلَيْهِ فَيَدُقُّهُ فَعِنْدَ ذَلِكَ يَغْدِرُ ‏ ‏الرُّومُ ‏ ‏وَيَجْمَعُونَ ‏ ‏لِلْمَلْحَمَةِ ‏","","",""],[16223,16223,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ هُوَ الْقُرْقُسَائِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏حَسَّانَ بْنِ عَطِيَّةَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏ذِي مِخْمَرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تُصَالِحُونَ ‏ ‏الرُّومَ ‏ ‏صُلْحًا آمِنًا وَتَغْزُونَ أَنْتُمْ وَهُمْ عَدُوًّا مِنْ وَرَائِهِمْ فَتَسْلَمُونَ وَتَغْنَمُونَ ثُمَّ تَنْزِلُونَ ‏ ‏بِمَرْجٍ ‏ ‏ذِي تُلُولٍ ‏ ‏فَيَقُومُ إِلَيْهِ رَجُلٌ مِنْ ‏ ‏الرُّومِ ‏ ‏فَيَرْفَعُ الصَّلِيبَ وَيَقُولُ أَلَا غَلَبَ الصَّلِيبُ فَيَقُومُ إِلَيْهِ رَجُلٌ مِنْ الْمُسْلِمِينَ فَيَقْتُلُهُ فَعِنْدَ ذَلِكَ تَغْدِرُ ‏ ‏الرُّومُ ‏ ‏وَتَكُونُ ‏ ‏الْمَلَاحِمُ ‏ ‏فَيَجْتَمِعُونَ إِلَيْكُمْ فَيَأْتُونَكُمْ فِي ثَمَانِينَ ‏ ‏غَايَةً ‏ ‏مَعَ كُلِّ ‏ ‏غَايَةٍ ‏ ‏عَشْرَةُ آلَافٍ ‏","","",""],[16224,16224,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْقُدُّوسِ أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَرِيزٌ يَعْنِي ابْنَ عُثْمَانَ الرَّحَبِيَّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏رَاشِدُ بْنُ سَعْدٍ الْمَقْرَائِيُّ ‏ ‏عَنْ ‏ ‏أَبِي حَيٍّ ‏ ‏عَنْ ‏ ‏ذِي مِخْمَرٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَانَ هَذَا الْأَمْرُ فِي ‏ ‏حِمْيَرَ ‏ ‏فَنَزَعَهُ اللَّهُ عَزَّ وَجَلَّ مِنْهُمْ فَجَعَلَهُ فِي ‏ ‏قُرَيْشٍ ‏ ‏وَ سَ يَ عُ ‏ ‏و ‏ ‏دُ إِ لَ يْ هِ مْ وَكَذَا كَانَ فِي كِتَابِ أَبِي مُقَطَّعًا وَحَيْثُ حَدَّثَنَا بِهِ تَكَلَّمَ عَلَى ‏ ‏الِاسْتِوَاءِ ‏","","",""],[16225,16225,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَأَبُو عَامِرٍ الْعَقَدِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ طَلْحَةَ ‏ ‏قَالَ ‏ ‏أَبُو عَامِرٍ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عِيسَى بْنُ طَلْحَةَ ‏ ‏قَالَ ‏ ‏دَخَلْنَا عَلَى ‏ ‏مُعَاوِيَةَ ‏ ‏فَنَادَى الْمُنَادِي بِالصَّلَاةِ فَقَالَ ‏ ‏اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ فَقَالَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ قَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏وَأَنَا أَشْهَدُ ‏ ‏قَالَ ‏ ‏أَبُو عَامِرٍ ‏ ‏أَنْ لَا إِلَهَ إِلَّا اللَّهُ ‏ ‏قَالَ أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ قَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏وَأَنَا أَشْهَدُ ‏ ‏قَالَ ‏ ‏أَبُو عَامِرٍ ‏ ‏أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏فَحَدَّثَنَا رَجُلٌ أَنَّهُ لَمَّا قَالَ حَيَّ عَلَى الصَّلَاةِ قَالَ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ قَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏هَكَذَا سَمِعْتُ نَبِيَّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏","","",""],[16226,16226,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏قَالَ ‏ ‏قَدِمَ ‏ ‏مُعَاوِيَةُ ‏ ‏الْمَدِينَةَ ‏ ‏فَخَطَبَنَا وَأَخْرَجَ ‏ ‏كُبَّةً ‏ ‏مِنْ شَعَرٍ فَقَالَ مَا كُنْتُ أَرَى أَنَّ أَحَدًا يَفْعَلُهُ إِلَّا ‏ ‏الْيَهُودَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَلَغَهُ ‏ ‏فَسَمَّاهُ ‏ ‏الزُّورَ ‏ ‏أَوْ ‏ ‏الزِّيرَ ‏ ‏شَكَّ ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏","","",""],[16227,16227,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ الشَّهِيدِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا مِجْلَزٍ ‏ ‏قَالَ ‏ ‏دَخَلَ ‏ ‏مُعَاوِيَةُ ‏ ‏عَلَى ‏ ‏عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏وَابْنِ عَامِرٍ ‏ ‏قَالَ فَقَامَ ‏ ‏ابْنُ عَامِرٍ ‏ ‏وَلَمْ يَقُمْ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏قَالَ وَكَانَ الشَّيْخُ أَوْزَنَهُمَا قَالَ قَالَ ‏ ‏مَهْ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَحَبَّ أَنْ يَمْثُلَ لَهُ عِبَادُ اللَّهِ قِيَامًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[16228,16228,"","","‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَجَدْتُ هَذَا الْحَدِيثَ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ وَهُوَ البُرْسَانِيُّ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمْرُو بْنُ يَحْيَى ‏ ‏أَنَّ ‏ ‏عِيسَى بْنَ عُمَرَ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَلْقَمَةَ بْنِ وَقَّاصٍ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ وَقَّاصٍ ‏ ‏قَالَ ‏ ‏إِنِّي لَعِنْدَ ‏ ‏مُعَاوِيَةَ ‏ ‏إِذْ أَذَّنَ مُؤَذِّنُهُ فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏كَمَا قَالَ الْمُؤَذِّنُ حَتَّى ‏ ‏إِذَا قَالَ حَيَّ عَلَى الصَّلَاةِ قَالَ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ فَلَمَّا قَالَ حَيَّ عَلَى الْفَلَاحِ قَالَ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ وَقَالَ بَعْدَ ذَلِكَ مَا قَالَ الْمُؤَذِّنُ ثُمَّ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ذَلِكَ ‏","","",""],[16229,16229,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏أَنَّ ‏ ‏مُعَاوِيَةَ ‏ ‏دَخَلَ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَقَالَتْ لَهُ أَمَا خِفْتَ أَنْ أُقْعِدَ لَكَ رَجُلًا فَيَقْتُلَكَ فَقَالَ مَا كُنْتِ لِتَفْعَلِيهِ وَأَنَا فِي بَيْتِ أَمَانٍ وَقَدْ سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَعْنِي ‏ ‏الْإِيمَانُ قَيْدُ الْفَتْكِ كَيْفَ أَنَا فِي الَّذِي بَيْنِي وَبَيْنَكِ وَفِي ‏ ‏حَوَائِجِكِ ‏ ‏قَالَتْ صَالِحٌ قَالَ فَدَعِينَا وَإِيَّاهُمْ حَتَّى نَلْقَى رَبَّنَا عَزَّ وَجَلَّ ‏","","",""],[16230,16230,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي شَيْخٍ الْهُنَائِيِّ ‏ ‏قَالَ ‏ ‏كُنْتُ فِي مَلَإٍ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ ‏ ‏مُعَاوِيَةَ ‏ ‏فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏أَنْشُدُكُمْ ‏ ‏اللَّهَ أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ لُبْسِ الْحَرِيرِ قَالُوا اللَّهُمَّ نَعَمْ قَالَ وَأَنَا أَشْهَدُ قَالَ ‏ ‏أَنْشُدُكُمْ ‏ ‏اللَّهَ تَعَالَى أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ لُبْسِ الذَّهَبِ إِلَّا مُقَطَّعًا قَالُوا اللَّهُمَّ نَعَمْ قَالَ وَأَنَا أَشْهَدُ قَالَ ‏ ‏أَنْشُدُكُمْ ‏ ‏اللَّهَ تَعَالَى أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ رُكُوبِ النُّمُورِ قَالُوا اللَّهُمَّ نَعَمْ قَالَ وَأَنَا أَشْهَدُ قَالَ ‏ ‏أَنْشُدُكُمْ ‏ ‏اللَّهَ تَعَالَى أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ الشُّرْبِ فِي آنِيَةِ الْفِضَّةِ قَالُوا اللَّهُمَّ نَعَمْ قَالَ وَأَنَا أَشْهَدُ قَالَ ‏ ‏أَنْشُدُكُمْ ‏ ‏اللَّهَ تَعَالَى أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ جَمْعٍ بَيْنَ حَجٍّ وَعُمْرَةٍ قَالُوا أَمَّا هَذَا فَلَا قَالَ أَمَا إِنَّهَا مَعَهُنَّ ‏","","",""],[16231,16231,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏جَبَلَةُ بْنُ عَطِيَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَيْرِيزٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَرَادَ اللَّهُ بِعَبْدٍ خَيْرًا ‏ ‏فَقَّهَهُ ‏ ‏فِي الدِّينِ ‏","","",""],[16232,16232,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَرْحُومُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو نَعَامَةَ السَّعْدِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏خَرَجَ ‏ ‏مُعَاوِيَةُ ‏ ‏عَلَى حَلْقَةٍ فِي الْمَسْجِدِ فَقَالَ مَا أَجْلَسَكُمْ قَالُوا جَلَسْنَا نَذْكُرُ اللَّهَ عَزَّ وَجَلَّ قَالَ ‏ ‏آللَّهِ مَا أَجْلَسَكُمْ إِلَّا ذَاكَ قَالُوا ‏ ‏آللَّهِ مَا أَجْلَسَنَا إِلَّا ذَاكَ قَالَ أَمَا إِنِّي لَمْ أَسْتَحْلِفْكُمْ تُهْمَةً لَكُمْ وَمَا كَانَ أَحَدٌ بِمَنْزِلَتِي مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَقَلَّ عَنْهُ حَدِيثًا مِنِّي وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ عَلَى حَلْقَةٍ مِنْ أَصْحَابِهِ فَقَالَ ‏ ‏مَا أَجْلَسَكُمْ قَالُوا جَلَسْنَا نَذْكُرُ اللَّهَ عَزَّ وَجَلَّ وَنَحْمَدُهُ عَلَى مَا هَدَانَا لِلْإِسْلَامِ وَمَنَّ عَلَيْنَا بِكَ قَالَ ‏ ‏آللَّهِ مَا أَجْلَسَكُمْ إِلَّا ذَلِكَ قَالُوا ‏ ‏آللَّهِ مَا أَجْلَسَنَا إِلَّا ذَلِكَ قَالَ أَمَا إِنِّي لَمْ أَسْتَحْلِفْكُمْ تُهْمَةً لَكُمْ وَإِنَّهُ أَتَانِي ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَأَخْبَرَنِي أَنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏يُبَاهِي بِكُمْ الْمَلَائِكَةَ ‏","","",""],[16233,16233,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏قَيْسٌ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏أَنَّ ‏ ‏مُعَاوِيَةَ بْنَ أَبِي سُفْيَانَ بْنِ حَرْبٍ ‏ ‏أَخَذَ مِنْ أَطْرَافِ ‏ ‏يَعْنِي شَعَرَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏أَيَّامِ الْعَشْرِ ‏ ‏بِمِشْقَصٍ ‏ ‏مَعِي وَهُوَ مُحْرِمٌ وَالنَّاسُ يُنْكِرُونَ ذَلِكَ ‏","","",""],[16234,16234,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَنْبَأَنِي ‏ ‏سَعْدُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏مَعْبَدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏مُعَاوِيَةُ ‏ ‏قَلَّمَا يُحَدِّثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَيْئًا وَيَقُولُ هَؤُلَاءِ الْكَلِمَاتِ قَلَّمَا يَدَعُهُنَّ أَوْ يُحَدِّثُ بِهِنَّ فِي الْجُمَعِ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ يُرِدْ اللَّهُ بِهِ خَيْرًا يُفَقِّهُّ فِي الدِّينِ وَإِنَّ هَذَا الْمَالَ حُلْوٌ خَضِرٌ فَمَنْ يَأْخُذْهُ بِحَقِّهِ يُبَارَكْ لَهُ فِيهِ وَإِيَّاكُمْ وَالتَّمَادُحَ فَإِنَّهُ الذَّبْحُ ‏","","",""],[16235,16235,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنِ ‏ ‏ابْنِ مُحَيْرِيزٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏تُبَادِرُونِي ‏ ‏بِرُكُوعٍ وَلَا بِسُجُودٍ فَإِنَّهُ مَهْمَا أَسْبِقْكُمْ بِهِ إِذَا رَكَعْتُ تُدْرِكُونِي إِذَا رَفَعْتُ وَمَهْمَا أَسْبِقْكُمْ بِهِ إِذَا سَجَدْتُ تُدْرِكُونِي إِذَا رَفَعْتُ إِنِّي قَدْ ‏ ‏بَدَّنْتُ ‏","","",""],[16236,16236,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ كَعْبٍ الْقُرَظِيِّ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏عَلَى الْمِنْبَرِ ‏ ‏اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ وَلَا مُعْطِيَ لِمَا مَنَعْتَ وَلَا يَنْفَعُ ذَا ‏ ‏الْجَدِّ ‏ ‏مِنْكَ ‏ ‏الْجَدُّ ‏ ‏مَنْ يُرِدْ اللَّهُ بِهِ خَيْرًا يُفَقِّهُّ فِي الدِّينِ سَمِعْتُ هَؤُلَاءِ الْكَلِمَاتِ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى هَذَا الْمِنْبَرِ ‏","","",""],[16237,16237,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُعْتَمِرِ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَرْكَبُوا ‏ ‏الْخَزَّ ‏ ‏وَلَا ‏ ‏النِّمَارَ ‏ ‏قَالَ ‏ ‏ابْنُ سِيرِينَ ‏ ‏وَكَانَ ‏ ‏مُعَاوِيَةُ ‏ ‏لَا يُتَّهَمُ فِي الْحَدِيثِ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏يُقَالُ لَهُ ‏ ‏الْحَبَرِيُّ يَعْنِي أَبَا الْمُعْتَمِرِ ‏ ‏وَيَزِيدُ بْنُ طَهْمَانَ أَبُو الْمُعْتَمِرِ ‏ ‏هَذَا ‏","","",""],[16238,16238,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مُجَمِّعُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ بْنِ سَهْلٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَتَشَهَّدُ مَعَ الْمُؤَذِّنِينَ ‏","","",""],[16239,16239,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏جَبَلَةَ بْنِ عَطِيَّةَ ‏ ‏عَنِ ‏ ‏ابْنِ مُحَيْرِيزٍ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَيْرِيزٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ اللَّهُ عَزَّ وَجَلَّ بِعَبْدٍ خَيْرًا يُفَقِّهُّ فِي الدِّينِ ‏","","",""],[16240,16240,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلَكِ بْنُ عَمْرٍو ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏قَالَ قَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏ذَاتَ يَوْمٍ إِنَّكُمْ قَدْ أَحْدَثْتُمْ زِيَّ سُوءٍ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الزُّورِ ‏ ‏وَقَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏الزُّورُ ‏ ‏قَالَ وَجَاءَ رَجُلٌ بِعَصًا عَلَى رَأْسِهَا ‏ ‏خِرْقَةٌ ‏ ‏فَقَالَ أَلَا وَهَذَا ‏ ‏الزُّورُ ‏ ‏قَالَ ‏ ‏أَبُو عَامِرٍ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏هُوَ مَا يُكْثِرُ بِهِ النِّسَاءُ أَشْعَارَهُنَّ مِنْ الْخِرَقِ ‏","","",""],[16241,16241,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏مَيْمُونٍ الْقَنَّادِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ رُكُوبِ ‏ ‏النِّمَارِ وَعَنْ لُبْسِ الذَّهَبِ إِلَّا مُقَطَّعًا ‏","","",""],[16242,16242,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏حَبِيبُ بْنُ الشَّهِيدِ ‏ ‏عَنْ ‏ ‏أَبِي مِجْلَزٍ ‏ ‏أَنَّ ‏ ‏مُعَاوِيَةَ ‏ ‏دَخَلَ بَيْتًا فِيهِ ‏ ‏ابْنُ عَامِرٍ ‏ ‏وَابْنُ الزُّبَيْرِ ‏ ‏فَقَامَ ‏ ‏ابْنُ عَامِرٍ ‏ ‏وَجَلَسَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏فَقَالَ لَهُ ‏ ‏مُعَاوِيَةُ ‏ ‏اجْلِسْ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ سَرَّهُ أَنْ ‏ ‏يَمْثُلَ ‏ ‏لَهُ الْعِبَادُ قِيَامًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏بَيْتًا فِي النَّارِ ‏","","",""],[16243,16243,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏مَعْبَدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏مُعَاوِيَةُ ‏ ‏قَلَّمَا يُحَدِّثُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَكَانَ قَلَّمَا يَكَادُ أَنْ يَدَعَ يَوْمَ الْجُمُعَةِ هَؤُلَاءِ الْكَلِمَاتِ أَنْ يُحَدِّثَ بِهِنَّ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ يُرِدْ اللَّهُ بِهِ خَيْرًا يُفَقِّهُّ فِي الدِّينِ وَإِنَّ هَذَا الْمَالَ حُلْوٌ خَضِرٌ فَمَنْ يَأْخُذْهُ بِحَقِّهِ يُبَارَكْ لَهُ فِيهِ وَإِيَّاكُمْ وَالتَّمَادُحَ فَإِنَّهُ الذَّبْحُ ‏","","",""],[16244,16244,"","","‏ ‏حَدَّثَنَا ‏ ‏عَارِمٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنِ ‏ ‏الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏مَعْبَدٍ الْقَاصِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ شَرِبَ الْخَمْرَ فَاجْلِدُوهُ فَإِنْ عَادَ فَاجْلِدُوهُ فَإِنْ عَادَ فَاجْلِدُوهُ فَإِنْ عَادَ الرَّابِعَةَ فَاقْتُلُوهُ ‏","","",""],[16245,16245,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏حَرِيزٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي عَوْفٍ الْجُرَشِيِّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمُصُّ لِسَانَهُ ‏ ‏أَوْ قَالَ شَفَتَهُ ‏ ‏يَعْنِي ‏ ‏الْحَسَنَ بْنَ عَلِيٍّ ‏ ‏صَلَوَاتُ اللَّهِ عَلَيْهِ ‏ ‏وَإِنَّهُ ‏ ‏لَنْ يُعَذَّبَ لِسَانٌ أَوْ شَفَتَانِ مَصَّهُمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[16246,16246,"","","‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَعْفَرٌ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ الْأَصَمِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُعَاوِيَةَ بْنَ أَبِي سُفْيَانَ ‏ ‏ذَكَرَ حَدِيثًا ‏ ‏رَوَاهُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ أَسْمَعْهُ رَوَى عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدِيثًا غَيْرَهُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ يُرِدْ اللَّهُ بِهِ خَيْرًا يُفَقِّهُّ فِي الدِّينِ وَلَا تَزَالُ عِصَابَةٌ مِنْ الْمُسْلِمِينَ يُقَاتِلُونَ عَلَى الْحَقِّ ظَاهِرِينَ عَلَى مَنْ ‏ ‏نَاوَأَهُمْ ‏ ‏إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[16247,16247,"","","‏ ‏حَدَّثَنَا ‏ ‏شُجَاعُ بْنُ الْوَلِيدِ ‏ ‏قَالَ ذَكَرَ ‏ ‏عُثْمَانُ بْنُ حَكِيمٍ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ عَلَى هَذِهِ الْأَعْوَادِ ‏ ‏اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ وَلَا مُعْطِيَ لِمَا مَنَعْتَ وَلَا يَنْفَعُ ذَا ‏ ‏الْجَدِّ ‏ ‏مِنْكَ ‏ ‏الْجَدُّ ‏ ‏مَنْ يُرِدْ اللَّهُ بِهِ الْخَيْرَ يُفَقِّهُّ فِي الدِّينِ ‏","","",""],[16248,16248,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏قَالَ ‏ ‏خَطَبَ ‏ ‏مُعَاوِيَةُ ‏ ‏عَلَى مِنْبَرِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ مِنْبَرِ ‏ ‏الْمَدِينَةِ ‏ ‏فَأَخْرَجَ ‏ ‏كُبَّةً ‏ ‏مِنْ شَعَرٍ قَالَ مَا كُنْتُ أَرَى أَنَّ أَحَدًا يَفْعَلُ هَذَا غَيْرَ ‏ ‏الْيَهُودِ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمَّاهُ ‏ ‏الزُّورَ ‏","","",""],[16249,16249,"","","‏ ‏حَدَّثَنَا ‏ ‏بِشْرُ بْنُ شُعَيْبِ بْنِ أَبِي حَمْزَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏مُحَمَّدُ بْنُ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّهُ بَلَغَ ‏ ‏مُعَاوِيَةَ ‏ ‏وَهُوَ عِنْدَهُ فِي وَفْدٍ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عَمْرِو بْنِ الْعَاصِ ‏ ‏يُحَدِّثُ أَنَّهُ سَيَكُونُ مَلِكٌ مِنْ ‏ ‏قَحْطَانَ ‏ ‏فَغَضِبَ ‏ ‏مُعَاوِيَةُ ‏ ‏فَقَامَ فَأَثْنَى عَلَى اللَّهِ عَزَّ وَجَلَّ بِمَا هُوَ أَهْلُهُ ثُمَّ قَالَ أَمَّا بَعْدُ فَإِنَّهُ بَلَغَنِي أَنَّ رِجَالًا مِنْكُمْ يُحَدِّثُونَ أَحَادِيثَ لَيْسَتْ فِي كِتَابِ اللَّهِ وَلَا تُؤْثَرُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُولَئِكَ جُهَّالُكُمْ فَإِيَّاكُمْ وَالْأَمَانِيَّ الَّتِي تُضِلُّ أَهْلَهَا فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ هَذَا الْأَمْرَ فِي ‏ ‏قُرَيْشٍ ‏ ‏لَا يُنَازِعُهُمْ أَحَدٌ إِلَّا ‏ ‏أَكَبَّهُ ‏ ‏اللَّهُ عَلَى وَجْهِهِ مَا أَقَامُوا الدِّينَ ‏","","",""],[16250,16250,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ يَزِيدَ بْنِ جَابِرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو عَبْدِ رَبِّهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُعَاوِيَةَ ‏ ‏يَقُولُ ‏ ‏عَلَى هَذَا الْمِنْبَرِ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ مَا بَقِيَ مِنْ الدُّنْيَا ‏ ‏بَلَاءٌ ‏ ‏وَفِتْنَةٌ ‏ ‏وَإِنَّمَا مَثَلُ عَمَلِ أَحَدِكُمْ كَمَثَلِ الْوِعَاءِ إِذَا طَابَ أَعْلَاهُ طَابَ أَسْفَلُهُ وَإِذَا خَبُثَ أَعْلَاهُ خَبُثَ أَسْفَلُهُ ‏","","",""],[16251,16251,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْعَلَاءِ ‏ ‏عَنْ ‏ ‏أَبِي الْأَزْهَرِ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏أَنَّهُ ‏ ‏ذَكَرَ لَهُمْ وُضُوءَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَّهُ ‏ ‏مَسَحَ رَأْسَهُ بِغَرْفَةٍ مِنْ مَاءٍ حَتَّى يَقْطُرَ الْمَاءُ مِنْ رَأْسِهِ ‏ ‏أَوْ كَادَ يَقْطُرُ ‏ ‏وَأَنَّهُ أَرَاهُمْ وُضُوءَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا بَلَغَ مَسْحَ رَأْسِهِ وَضَعَ كَفَّيْهِ عَلَى مُقَدَّمِ رَأْسِهِ ثُمَّ مَرَّ بِهِمَا حَتَّى بَلَغَ الْقَفَا ثُمَّ رَدَّهُمَا حَتَّى بَلَغَ الْمَكَانَ الَّذِي بَدَأَ مِنْهُ ‏","","",""],[16252,16252,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْوَلِيدُ يَعْنِي ابْنَ مُسْلِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْعَلَاءِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏يَزِيدَ يَعْنِي ابْنَ أَبِي مَالِكٍ ‏ ‏وَأَبَا الْأَزْهَرِ ‏ ‏يُحَدِّثَانِ عَنْ وُضُوءِ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ يُرِيهِمْ وُضُوءَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَوَضَّأَ ثَلَاثًا ثَلَاثًا وَغَسَلَ رِجْلَيْهِ بِغَيْرِ عَدَدٍ ‏","","",""],[16253,16253,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏وَسَعْدٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ هُرْمُزَ الْأَعْرَجُ ‏ ‏أَنَّ ‏ ‏الْعَبَّاسَ بْنَ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏أَنْكَحَ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ الْحَكَمِ ‏ ‏ابْنَتَهُ وَأَنْكَحَهُ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏ابْنَتَهُ وَقَدْ كَانَا جَعَلَا ‏ ‏صَدَاقًا ‏ ‏فَكَتَبَ ‏ ‏مُعَاوِيَةُ بْنُ أَبِي سُفْيَانَ ‏ ‏وَهُوَ خَلِيفَةٌ إِلَى ‏ ‏مَرْوَانَ ‏ ‏يَأْمُرُهُ بِالتَّفْرِيقِ بَيْنَهُمَا وَقَالَ فِي كِتَابِهِ ‏ ‏هَذَا ‏ ‏الشِّغَارُ ‏ ‏الَّذِي نَهَى عَنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[16254,16254,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَقَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ عَبَّادِ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَبَّادٍ ‏ ‏قَالَ ‏ ‏لَمَّا قَدِمَ عَلَيْنَا ‏ ‏مُعَاوِيَةُ ‏ ‏حَاجًّا قَدِمْنَا مَعَهُ ‏ ‏مَكَّةَ ‏ ‏قَالَ فَصَلَّى بِنَا الظُّهْرَ رَكْعَتَيْنِ ثُمَّ انْصَرَفَ إِلَى دَارِ النَّدْوَةِ قَالَ وَكَانَ ‏ ‏عُثْمَانُ ‏ ‏حِينَ أَتَمَّ الصَّلَاةَ إِذَا قَدِمَ ‏ ‏مَكَّةَ ‏ ‏صَلَّى بِهَا الظُّهْرَ وَالْعَصْرَ وَالْعِشَاءَ الْآخِرَةَ أَرْبَعًا أَرْبَعًا فَإِذَا خَرَجَ إِلَى ‏ ‏مِنًى ‏ ‏وَعَرَفَاتٍ ‏ ‏قَصَرَ الصَّلَاةَ فَإِذَا فَرَغَ مِنْ الْحَجِّ وَأَقَامَ ‏ ‏بِمِنًى ‏ ‏أَتَمَّ الصَّلَاةَ حَتَّى يَخْرُجَ مِنْ ‏ ‏مَكَّةَ ‏ ‏فَلَمَّا صَلَّى بِنَا الظُّهْرَ رَكْعَتَيْنِ نَهَضَ إِلَيْهِ ‏ ‏مَرْوَانُ بْنُ الْحَكَمِ ‏ ‏وَعَمْرُو بْنُ عُثْمَانَ ‏ ‏فَقَالَا لَهُ مَا عَابَ أَحَدٌ ابْنَ عَمِّكَ بِأَقْبَحِ مَا عِبْتَهُ بِهِ فَقَالَ لَهُمَا وَمَا ذَاكَ قَالَ فَقَالَا لَهُ أَلَمْ تَعْلَمْ أَنَّهُ أَتَمَّ الصَّلَاةَ ‏ ‏بِمَكَّةَ ‏ ‏قَالَ فَقَالَ لَهُمَا وَيْحَكُمَا وَهَلْ كَانَ غَيْرُ مَا صَنَعْتُ قَدْ ‏ ‏صَلَّيْتُهُمَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَعَ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمَا ‏ ‏قَالَا فَإِنَّ ابْنَ عَمِّكَ قَدْ كَانَ أَتَمَّهَا وَإِنَّ خِلَافَكَ إِيَّاهُ لَهُ عَيْبٌ قَالَ فَخَرَجَ ‏ ‏مُعَاوِيَةُ ‏ ‏إِلَى الْعَصْرِ فَصَلَّاهَا بِنَا أَرْبَعًا ‏","","",""],[16255,16255,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الطُّفَيْلِ ‏ ‏قَالَ ‏ ‏قَدِمَ ‏ ‏مُعَاوِيَةُ ‏ ‏وَابْنُ عَبَّاسٍ ‏ ‏فَطَافَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏فَاسْتَلَمَ الْأَرْكَانَ كُلَّهَا فَقَالَ لَهُ ‏ ‏مُعَاوِيَةُ ‏ ‏إِنَّمَا اسْتَلَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الرُّكْنَيْنِ الْيَمَانِيَّيْنِ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏لَيْسَ مِنْ أَرْكَانِهِ شَيْءٌ مَهْجُورٌ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏النَّاسُ يَخْتَلِفُونَ فِي هَذَا الْحَدِيثِ يَقُولُونَ ‏ ‏مُعَاوِيَةُ ‏ ‏هُوَ الَّذِي قَالَ لَيْسَ مِنْ ‏ ‏الْبَيْتِ ‏ ‏شَيْءٌ مَهْجُورٌ وَلَكِنَّهُ حَفِظَهُ مِنْ ‏ ‏قَتَادَةَ ‏ ‏هَكَذَا ‏","","",""],[16256,16256,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَاصِمَ بْنَ بَهْدَلَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا شَرِبُوا الْخَمْرَ فَاجْلِدُوهُمْ ثُمَّ إِذَا شَرِبُوا فَاجْلِدُوهُمْ ثُمَّ إِذَا شَرِبُوا فَاجْلِدُوهُمْ ثُمَّ إِذَا شَرِبُوهَا الرَّابِعَةَ فَاقْتُلُوهُمْ ‏","","",""],[16257,16257,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏وَيَعْلَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ حَكِيمٍ ‏ ‏وَأَبُو بَدْرٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ كَعْبٍ الْقُرَظِيِّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ ‏ ‏يَعْلَى ‏ ‏فِي حَدِيثِهِ ‏ ‏سَمِعْتُ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ عَلَى هَذِهِ الْأَعْوَادِ ‏ ‏اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ وَلَا مُعْطِيَ لِمَا مَنَعْتَ مَنْ يُرِدْ اللَّهُ بِهِ خَيْرًا يُفَقِّهُّ فِي الدِّينِ ‏","","",""],[16258,16258,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏وَيَعْلَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏طَلْحَةُ يَعْنِي ابْنَ يَحْيَى ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ طَلْحَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُعَاوِيَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الْمُؤَذِّنِينَ أَطْوَلُ النَّاسِ أَعْنَاقًا يَوْمَ الْقِيَامَةِ ‏","","",""],[16259,16259,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى ‏ ‏وَيَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُجَمِّعُ بْنُ يَحْيَى الْأَنْصَارِيُّ ‏ ‏قَالَ ‏ ‏كُنْتُ إِلَى جَنْبِ ‏ ‏أَبِي أُمَامَةَ بْنِ سَهْلٍ ‏ ‏وَهُوَ مُسْتَقْبِلُ الْمُؤَذِّنِ ‏ ‏وَكَبَّرَ الْمُؤَذِّنُ اثْنَتَيْنِ فَكَبَّرَ ‏ ‏أَبُو أُمَامَةَ ‏ ‏اثْنَتَيْنِ وَشَهِدَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ اثْنَتَيْنِ فَشَهِدَ ‏ ‏أَبُو أُمَامَةَ ‏ ‏اثْنَتَيْنِ وَشَهِدَ الْمُؤَذِّنُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ اثْنَتَيْنِ وَشَهِدَ ‏ ‏أَبُو أُمَامَةَ ‏ ‏اثْنَتَيْنِ ثُمَّ الْتَفَتَ إِلَيَّ فَقَالَ هَكَذَا حَدَّثَنِي ‏ ‏مُعَاوِيَةُ بْنُ أَبِي سُفْيَانَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[16260,16260,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَمْرٍو مَرْوَانُ بْنُ شُجَاعٍ الْجَزَرِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خُصَيْفٌ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏وَعَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏مُعَاوِيَةَ ‏ ‏أخْبَرَهُ ‏ ‏أَنَّهُ رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَصَّرَ مِنْ شَعَرِهِ ‏ ‏بِمِشْقَصٍ ‏ ‏فَقُلْنَا ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏مَا بَلَغَنَا هَذَا إِلَّا عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏فَقَالَ ‏ ‏مَا كَانَ ‏ ‏مُعَاوِيَةُ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُتَّهَمًا ‏","","",""],[16261,16261,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي شَيْخٍ الْهُنَائِيِّ ‏ ‏أَنَّ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ لِنَفَرٍ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ جُلُودِ النُّمُورِ أَنْ يُرْكَبَ عَلَيْهَا قَالُوا اللَّهُمَّ نَعَمْ قَالَ وَتَعْلَمُونَ أَنَّهُ نَهَى عَنْ لِبَاسِ الذَّهَبِ إِلَّا مُقَطَّعًا قَالُوا اللَّهُمَّ نَعَمْ قَالَ وَتَعْلَمُونَ أَنَّهُ نَهَى عَنْ الشُّرْبِ فِي آنِيَةِ الذَّهَبِ وَالْفِضَّةِ قَالُوا اللَّهُمَّ نَعَمْ قَالَ وَتَعْلَمُونَ أَنَّهُ نَهَى عَنْ الْمُتْعَةِ ‏ ‏يَعْنِي مُتْعَةَ الْحَجِّ قَالُوا اللَّهُمَّ لَا ‏","","",""],[16262,16262,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّهُ ‏ ‏رَأَى ‏ ‏مُعَاوِيَةَ ‏ ‏يَخْطُبُ عَلَى الْمِنْبَرِ وَفِي يَدِهِ ‏ ‏قُصَّةٌ ‏ ‏مِنْ شَعَرٍ قَالَ سَمِعْتُهُ يَقُولُ أَيْنَ عُلَمَاؤُكُمْ يَا أَهْلَ ‏ ‏الْمَدِينَةِ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى عَنْ مِثْلِ هَذَا وَقَالَ إِنَّمَا عُذِّبَ ‏ ‏بَنُو إِسْرَائِيلَ ‏ ‏حِينَ اتَّخَذَتْ هَذِهِ نِسَاؤُهُمْ ‏","","",""],[16263,16263,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُمَرُ بْنُ عَطَاءِ بْنِ أَبِي الْخُوَارِ ‏ ‏أَنَّ ‏ ‏نَافِعَ بْنَ جُبَيْرٍ ‏ ‏أَرْسَلَهُ إِلَى ‏ ‏السَّائِبِ بْنِ يَزِيدَ ‏ ‏ابْنِ أُخْتِ ‏ ‏نَمِرٍ ‏ ‏يَسْأَلُهُ عَنْ شَيْءٍ رَآهُ مِنْهُ ‏ ‏مُعَاوِيَةُ ‏ ‏فِي الصَّلَاةِ فَقَالَ نَعَمْ صَلَّيْتُ مَعَهُ الْجُمُعَةَ فِي ‏ ‏الْمَقْصُورَةِ ‏ ‏فَلَمَّا سَلَّمَ قُمْتُ فِي مَقَامِي فَصَلَّيْتُ فَلَمَّا دَخَلَ أَرْسَلَ إِلَيَّ فَقَالَ لَا تَعُدْ لِمَا فَعَلْتَ إِذَا صَلَّيْتَ الْجُمُعَةَ فَلَا تَصِلْهَا بِصَلَاةٍ حَتَّى تَتَكَلَّمَ أَوْ تَخْرُجَ فَإِنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ بِذَلِكَ ‏ ‏لَا تُوصَلُ بِصَلَاةٍ حَتَّى تَخْرُجَ أَوْ تَتَكَلَّمَ ‏","","",""],[16264,16264,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏حُمَيْدُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏مُعَاوِيَةَ ‏ ‏يَخْطُبُ ‏ ‏بِالْمَدِينَةِ ‏ ‏يَقُولُ يَا أَهْلَ ‏ ‏الْمَدِينَةِ ‏ ‏أَيْنَ عُلَمَاؤُكُمْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏هَذَا ‏ ‏يَوْمُ عَاشُورَاءَ ‏ ‏وَلَمْ يُفْرَضْ عَلَيْنَا صِيَامُهُ فَمَنْ شَاءَ مِنْكُمْ أَنْ يَصُومَ فَلْيَصُمْ فَإِنِّي صَائِمٌ فَصَامَ النَّاسُ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏وَمُحَمَّدُ بْنُ أَبِي حَفْصَةَ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏مُعَاوِيَةَ بْنَ أَبِي سُفْيَانَ ‏ ‏يَوْمَ عَاشُورَاءَ عَامَ حَجَّ وَهُوَ عَلَى الْمِنْبَرِ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[16265,16265,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ أَبِي النَّجُودِ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي شَارِبِ الْخَمْرِ ‏ ‏إِذَا شَرِبَ الْخَمْرَ فَاجْلِدُوهُ ثُمَّ إِذَا شَرِبَ فَاجْلِدُوهُ ثُمَّ إِذَا شَرِبَ الثَّالِثَةَ فَاجْلِدُوهُ ثُمَّ إِذَا شَرِبَ الرَّابِعَةَ فَاضْرِبُوا عُنُقَهُ ‏","","",""],[16266,16266,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَرَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْحَسَنُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْعَبَّاسِ ‏ ‏أَنَّ ‏ ‏مُعَاوِيَةَ بْنَ أَبِي سُفْيَانَ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏أخْبَرَهُ ‏ ‏قَالَ ‏ ‏قَصَّرْتُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِشْقَصٍ ‏ ‏عَلَى ‏ ‏الْمَرْوَةِ ‏ ‏أَوْ رَأَيْتُهُ يُقَصَّرُ عَنْهُ ‏ ‏بِمِشْقَصٍ ‏ ‏عَلَى ‏ ‏الْمَرْوَةِ ‏","","",""],[16267,16267,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏أَنَّ ‏ ‏سَعْدَ بْنَ إِبْرَاهِيمَ ‏ ‏أَخْبَرَهُ عَنِ ‏ ‏الْحَكَمِ بْنِ مِينَاءَ ‏ ‏أَنَّ ‏ ‏يَزِيدَ بْنَ جَارِيَةَ الْأَنْصَارِيَّ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ كَانَ جَالِسًا فِي نَفَرٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَخَرَجَ عَلَيْهِمْ ‏ ‏مُعَاوِيَةُ ‏ ‏فَسَأَلَهُمْ عَنْ حَدِيثِهِمْ فَقَالُوا كُنَّا فِي حَدِيثٍ مِنْ حَدِيثِ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏أَلَا أَزِيدُكُمْ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا بَلَى يَا أَمِيرَ الْمُؤْمِنِينَ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَحَبَّ ‏ ‏الْأَنْصَارَ ‏ ‏أَحَبَّهُ اللَّهُ عَزَّ وَجَلَّ وَمَنْ أَبْغَضَ ‏ ‏الْأَنْصَارَ ‏ ‏أَبْغَضَهُ اللَّهُ عَزَّ وَجَلَّ ‏","","",""],[16268,16268,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ سَعِيدِ بْنِ أَبِي حُسَيْنٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَلِيَّ بْنَ عَلِيٍّ ‏ ‏رَجُلًا مِنْ ‏ ‏بَنِي عَبْدِ شَمْسٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَعَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏وَحَدَّثَنِي ‏ ‏عُمَرُ بْنُ سَعِيدٍ ‏ ‏أَنَّ ‏ ‏عَلِيَّ بْنَ عَبْدِ اللَّهِ بْنِ عَلِيٍّ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏مُعَاوِيَةَ ‏ ‏عَلَى الْمِنْبَرِ ‏ ‏بِمَكَّةَ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ لُبْسِ الذَّهَبِ وَالْحَرِيرِ ‏","","",""],[16269,16269,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَامِرَ بْنَ سَعْدٍ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏جَرِيرَ بْنَ عَبْدِ اللَّهِ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ ‏ ‏مُعَاوِيَةَ بْنَ أَبِي سُفْيَانَ ‏ ‏يَقُولُ وَهُوَ يَخْطُبُ ‏ ‏تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ابْنُ ثَلَاثٍ وَسِتِّينَ ‏ ‏وَتُوُفِّيَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏وَهُوَ ابْنُ ثَلَاثٍ وَسِتِّينَ ‏ ‏وَتُوُفِّيَ ‏ ‏عُمَرُ ‏ ‏وَهُوَ ابْنُ ثَلَاثٍ وَسِتِّينَ ‏ ‏قَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏وَأَنَا الْيَوْمَ ابْنُ ثَلَاثٍ وَسِتِّينَ ‏","","",""],[16270,16270,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏جَبَلَةَ بْنِ عَطِيَّةَ ‏ ‏عَنِ ‏ ‏ابْنِ مُحَيْرِيزٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَرَادَ اللَّهُ عَزَّ وَجَلَّ بِعَبْدٍ خَيْرًا يُفَقِّهُّ فِي الدِّينِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ هَذَا الْكَلَامَ فِي آخِرِ هَذَا الْحَدِيثِ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ مُتَّصِلًا بِهِ وَقَدْ خَطَّ عَلَيْهِ فَلَا أَدْرِي أَقَرَأَهُ عَلَيَّ أَمْ لَا وَإِنَّ السَّامِعَ الْمُطِيعَ لَا حُجَّةَ عَلَيْهِ وَإِنَّ السَّامِعَ الْعَاصِي لَا حُجَّةَ لَهُ ‏","","",""],[16271,16271,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ مَاتَ بِغَيْرِ إِمَامٍ مَاتَ مِيتَةً جَاهِلِيَّةً ‏","","",""],[16272,16272,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَرْبٌ يَعْنِي ابْنَ شَدَّادٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو شَيْخٍ الْهُنَائِيُّ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏حِمَّانَ ‏ ‏أَنَّ ‏ ‏مُعَاوِيَةَ ‏ ‏عَامَ حَجَّ جَمَعَ نَفَرًا مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْكَعْبَةِ ‏ ‏فَقَالَ أَسْأَلُكُمْ عَنْ أَشْيَاءَ فَأَخْبِرُونِي أَنْشُدُكُمْ اللَّهَ هَلْ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ لُبْسِ الْحَرِيرِ قَالُوا نَعَمْ قَالَ وَأَنَا أَشْهَدُ ثُمَّ قَالَ أَنْشُدُكُمْ بِاللَّهِ أَنَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ لُبْسِ الذَّهَبِ قَالُوا نَعَمْ قَالَ وَأَنَا أَشْهَدُ قَالَ أَنْشُدُكُمْ بِاللَّهِ أَنَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ لُبْسِ صُوفِ النُّمُورِ قَالُوا نَعَمْ قَالَ وَأَنَا أَشْهَدُ ‏","","",""],[16273,16273,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمَّادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ بْنُ الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏جَرَادٍ ‏ ‏رَجُلٍ مِنْ ‏ ‏بَنِي تَمِيمٍ ‏ ‏عَنْ ‏ ‏رَجَاءِ بْنِ حَيْوَةَ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ يُرِدْ اللَّهُ بِهِ خَيْرًا يُفَقِّهُّ فِي الدِّينِ ‏","","",""],[16274,16274,"","","‏ ‏مَضْرُوبٌ عَلَيْهِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ هَذَا الْحَدِيثَ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ يَزِيدَ ‏ ‏وَأَظُنُّنِي قَدْ سَمِعْتُهُ مِنْهُ فِي الْمُذَاكَرَةِ فَلَمْ أَكْتُبْهُ وَكَانَ ‏ ‏بَكْرٌ ‏ ‏يَنْزِلُ ‏ ‏الْمَدِينَةَ ‏ ‏أَظُنُّهُ كَانَ فِي الْمِحْنَةِ كَانَ قَدْ ضُرِبَ عَلَى هَذَا ‏ ‏الْحَدِيثِ فِي كِتَابِهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَكْرُ بْنُ يَزِيدَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو بَكْرٍ يَعْنِي ابْنَ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏عَطِيَّةَ بْنِ قَيْسٍ الْكِلَابِيِّ ‏ ‏أَنَّ ‏ ‏مُعَاوِيَةَ بْنَ أَبِي سُفْيَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْعَيْنَيْنِ ‏ ‏وِكَاءُ ‏ ‏السَّهِ ‏ ‏فَإِذَا نَامَتْ الْعَيْنَانِ ‏ ‏اسْتُطْلِقَ ‏ ‏الْوِكَاءُ ‏","","",""],[16275,16275,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ يَزِيدَ الدِّمَشْقِيِّ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَامِرٍ الْيَحْصَبِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُعَاوِيَةَ بْنَ أَبِي سُفْيَانَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا أَرَادَ اللَّهُ عَزَّ وَجَلَّ بِعَبْدٍ خَيْرًا فَقَّهَهُ فِي الدِّينِ ‏","","",""],[16276,16276,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ عَبْدِ اللَّهِ الْيَحْصَبِيِّ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏كَذَا قَالَ ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏وَإِنَّمَا هُوَ ‏ ‏عَبْدُ اللَّهِ بْنُ عَامِرٍ الْيَحْصَبِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُعَاوِيَةَ بْنَ أَبِي سُفْيَانَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي عَلَى الْحَقِّ لَا يُبَالُونَ مَنْ خَالَفَهُمْ أَوْ خَذَلَهُمْ حَتَّى يَأْتِيَ أَمْرُ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[16277,16277,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏أَبِي السَّفَرِ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏مُعَاوِيَةَ ‏ ‏فَقَالَ ‏ ‏تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ابْنُ ثَلَاثٍ وَسِتِّينَ ‏ ‏وَتُوُفِّيَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَهُوَ ابْنُ ثَلَاثٍ وَسِتِّينَ ‏ ‏وَتُوُفِّيَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَهُوَ ابْنُ ثَلَاثٍ وَسِتِّينَ ‏","","",""],[16278,16278,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَلِيِّ ابْنِ الْحَنَفِيَّةِ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْعُمْرَى جَائِزَةٌ لِأَهْلِهَا ‏","","",""],[16279,16279,"","","‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ مُحَمَّدِ بْنِ بُكَيْرٍ النَّاقِدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ حُجَيْرٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ قَالَ لِي ‏ ‏مُعَاوِيَةُ ‏ ‏عَلِمْتَ أَنِّي ‏ ‏قَصَّرْتُ ‏ ‏مِنْ رَأْسِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِشْقَصٍ ‏ ‏فَقُلْتُ لَهُ لَا أَعْلَمُ هَذَا إِلَّا ‏ ‏حُجَّةً ‏ ‏عَلَيْكَ ‏","","",""],[16280,16280,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ مُحَمَّدٍ النَّاقِدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ ‏ ‏قَصَّرْتُ عَنْ رَأْسِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ ‏ ‏الْمَرْوَةِ ‏","","",""],[16281,16281,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ الْأَسَدِيُّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَصِّرُ ‏ ‏بِمِشْقَصٍ ‏","","",""],[16282,16282,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ أَبُو مَعْمَرٍ ‏ ‏وَمُحَمَّدُ بْنُ عَبَّادٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ حُجَيْرٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏أَمَا عَلِمْتَ أَنِّي ‏ ‏قَصَّرْتُ مِنْ رَأْسِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِشْقَصٍ ‏ ‏فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏لَا ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّادٍ ‏ ‏فِي حَدِيثِهِ قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏وَهَذِهِ حُجَّةٌ عَلَى ‏ ‏مُعَاوِيَةَ ‏","","",""],[16283,16283,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏مَعْبَدِ بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ شَرِبَ الْخَمْرَ فَاضْرِبُوهُ فَإِنْ عَادَ فَاضْرِبُوهُ فَإِنْ عَادَ فَاضْرِبُوهُ فَإِنْ عَادَ فَاقْتُلُوهُ ‏","","",""],[16284,16284,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ حَكِيمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُحَمَّدَ بْنَ كَعْبٍ الْقُرَظِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُعَاوِيَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِذَا انْصَرَفَ مِنْ الصَّلَاةِ اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ وَلَا مُعْطِيَ لِمَا مَنَعْتَ وَلَا يَنْفَعُ ذَا ‏ ‏الْجَدِّ ‏ ‏مِنْكَ ‏ ‏الْجَدُّ ‏","","",""],[16285,16285,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ الْهَيْثَمِ أَبُو قَطَنٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ ‏ ‏مَاتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ابْنُ ثَلَاثٍ وَسِتِّينَ سَنَةً ‏ ‏وَمَاتَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَهُوَ ابْنُ ثَلَاثٍ وَسِتِّينَ ‏ ‏وَمَاتَ ‏ ‏عُمَرُ ‏ ‏وَهُوَ ابْنُ ثَلَاثٍ وَسِتِّينَ ‏ ‏وَأَنَا الْيَوْمَ ابْنُ ثَلَاثٍ وَسِتِّينَ ‏","","",""],[16286,16286,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ مُعَاوِيَةَ ‏ ‏سَمِعَ ‏ ‏مُعَاوِيَةَ ‏ ‏يَقُولُ ‏ ‏بِالْمَدِينَةِ ‏ ‏عَلَى مِنْبَرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيْنَ عُلَمَاؤُكُمْ يَا أَهْلَ ‏ ‏الْمَدِينَةِ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي هَذَا الْيَوْمِ ‏ ‏يَوْمِ عَاشُورَاءَ ‏ ‏وَهُوَ ‏ ‏يَقُولُ ‏ ‏مَنْ شَاءَ مِنْكُمْ أَنْ يَصُومَهُ فَلْيَصُمْهُ ‏","","",""],[16287,16287,"","","‏ ‏وَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى عَنْ مِثْلِ هَذَا وَأَخْرَجَ ‏ ‏قُصَّةً ‏ ‏مِنْ شَعَرٍ مِنْ كُمِّهِ فَقَالَ إِنَّمَا هَلَكَتْ ‏ ‏بَنُو إِسْرَائِيلَ ‏ ‏حِينَ اتَّخَذَتْهَا نِسَاؤُهُمْ ‏","","",""],[16288,16288,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى بْنِ حَبَّانَ ‏ ‏عَنِ ‏ ‏ابْنِ مُحَيْرِيزٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تُبَادِرُونِي ‏ ‏فِي الرُّكُوعِ وَالسُّجُودِ فَإِنِّي قَدْ ‏ ‏بَدَّنْتُ ‏ ‏وَمَهْمَا أَسْبِقْكُمْ بِهِ إِذَا رَكَعْتُ تُدْرِكُونِي إِذَا رَفَعْتُ وَمَهْمَا أَسْبِقْكُمْ بِهِ إِذَا سَجَدْتُ تُدْرِكُونِي إِذَا رَفَعْتُ ‏","","",""],[16289,16289,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنِ ‏ ‏ابْنِ مُنَبِّهٍ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تُلْحِفُوا فِي الْمَسْأَلَةِ فَوَاللَّهِ لَا يَسْأَلُنِي أَحَدٌ شَيْئًا فَتَخْرُجَ لَهُ مَسْأَلَتُهُ فَيُبَارَكَ لَهُ فِيهِ ‏","","",""],[16290,16290,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ كَعْبٍ يَعْنِي الْقُرَظِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُعَاوِيَةَ ‏ ‏يَخْطُبُ عَلَى هَذَا الْمِنْبَرِ يَقُولُ تَعَلَّمُنَّ أَنَّهُ ‏ ‏لَا مَانِعَ لِمَا أَعْطَى وَلَا مُعْطِيَ لِمَا مَنَعَ اللَّهُ وَلَا يَنْفَعُ ذَا ‏ ‏الْجَدِّ ‏ ‏مِنْهُ ‏ ‏الْجَدُّ ‏ ‏مَنْ يُرِدْ اللَّهُ بِهِ خَيْرًا يُفَقِّهُّ فِي الدِّينِ سَمِعْتُ هَذِهِ الْأَحْرُفَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى هَذِهِ الْأَعْوَادِ ‏","","",""],[16291,16291,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏حَسَنُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏أَنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏أخْبَرَهُ أَنَّ ‏ ‏مُعَاوِيَةَ ‏ ‏أخْبَرَهُ ‏ ‏قَالَ ‏ ‏قَصَّرْتُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِشْقَصٍ ‏ ‏أَوْ قَالَ رَأَيْتُهُ يُقَصَّرُ عَنْهُ ‏ ‏بِمِشْقَصٍ ‏ ‏عِنْدَ ‏ ‏الْمَرْوَةِ ‏","","",""],[16292,16292,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرٍو ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏جَدِّي ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ ‏ ‏مُعَاوِيَةَ ‏ ‏فَقَالَ الْمُؤَذِّنُ ‏ ‏اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ فَقَالَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ فَقَالَ أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ فَقَالَ أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ فَقَالَ حَيَّ عَلَى الصَّلَاةِ فَقَالَ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ فَقَالَ حَيَّ عَلَى الْفَلَاحِ فَقَالَ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ فَقَالَ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ فَقَالَ اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ فَقَالَ لَا إِلَهَ إِلَّا اللَّهُ قَالَ لَا إِلَهَ إِلَّا اللَّهُ فَقَالَ هَكَذَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَوْ نَبِيُّكُمْ ‏ ‏إِذَا أَذَّنَ الْمُؤَذِّنُ ‏","","",""],[16293,16293,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي الطُّفَيْلِ ‏ ‏قَالَ ‏ ‏حَجَّ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏وَمُعَاوِيَةُ ‏ ‏فَجَعَلَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يَسْتَلِمُ الْأَرْكَانَ كُلَّهَا فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏إِنَّمَا اسْتَلَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَيْنِ الرُّكْنَيْنِ الْيَمَانِيَّيْنِ ‏ ‏فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏لَيْسَ مِنْ أَرْكَانِهِ مَهْجُورٌ ‏","","",""],[16294,16294,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏طَلْحَةُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ طَلْحَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُعَاوِيَةَ ‏ ‏يَقُولُ ‏ ‏إِذَا أَتَاهُ الْمُؤَذِّنُ يُؤْذِنُهُ بِالصَّلَاةِ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الْمُؤَذِّنِينَ أَطْوَلُ النَّاسِ أَعْنَاقًا يَوْمَ الْقِيَامَةِ ‏","","",""],[16295,16295,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏طَلْحَةُ يَعْنِي ابْنَ يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ شَيْءٍ يُصِيبُ الْمُؤْمِنَ فِي جَسَدِهِ ‏ ‏يُؤْذِيهِ إِلَّا كَفَّرَ اللَّهُ عَنْهُ بِهِ مِنْ سَيِّئَاتِهِ ‏","","",""],[16296,16296,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِينَ ‏ ‏يُشَقِّقُونَ ‏ ‏الْكَلَامَ ‏ ‏تَشْقِيقَ ‏ ‏الشِّعْرِ ‏","","",""],[16297,16297,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بَيْهَسُ بْنُ فَهْدَانَ ‏ ‏عَنْ ‏ ‏أَبِي شَيْخٍ الْهُنَائِيِّ ‏ ‏سَمِعْتُهُ مِنْهُ عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ لُبْسِ الذَّهَبِ إِلَّا مُقَطَّعًا ‏","","",""],[16298,16298,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُجَمِّعُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ بْنِ سَهْلٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَتَشَهَّدُ مَعَ الْمُؤَذِّنِينَ ‏","","",""],[16299,16299,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَعْبَدٍ الْجُهَنِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُعَاوِيَةَ ‏ ‏وَكَانَ قَلِيلَ الْحَدِيثِ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ قَلَّمَا خَطَبَ إِلَّا ذَكَرَ هَذَا الْحَدِيثَ فِي خُطْبَتِهِ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ هَذَا الْمَالَ حُلْوٌ خَضِرٌ فَمَنْ أَخَذَهُ بِحَقِّهِ بَارِكَ ‏ ‏اللَّهُ عَزَّ وَجَلَّ لَهُ فِيهِ وَمَنْ يُرِدْ اللَّهُ بِهِ خَيْرًا يُفَقِّهُّ فِي الدِّينِ وَإِيَّاكُمْ وَالْمَدْحَ فَإِنَّهُ الذَّبْحُ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ قَالَ فِيهِ ‏ ‏وَإِيَّاكُمْ وَالتَّمَادُحَ فَإِنَّهُ الذَّبْحُ ‏","","",""],[16300,16300,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ ابْنِ الْحَنَفِيَّةِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُعَاوِيَةَ بْنَ أَبِي سُفْيَانَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعُمْرَى جَائِزَةٌ لِأَهْلِهَا ‏","","",""],[16301,16301,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَرِيزُ بْنُ عُثْمَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي عَوْفٍ الْجُرَشِيُّ ‏ ‏عَنْ ‏ ‏أَبِي هِنْدٍ الْبَجَلِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا عِنْدَ ‏ ‏مُعَاوِيَةَ ‏ ‏وَهُوَ عَلَى سَرِيرِهِ وَقَدْ غَمَّضَ عَيْنَيْهِ فَتَذَاكَرْنَا الْهِجْرَةَ وَالْقَائِلُ مِنَّا يَقُولُ انْقَطَعَتْ وَالْقَائِلُ مِنَّا يَقُولُ لَمْ تَنْقَطِعْ فَاسْتَنْبَهَ ‏ ‏مُعَاوِيَةُ ‏ ‏فَقَالَ مَا كُنْتُمْ فِيهِ فَأَخْبَرْنَاهُ وَكَانَ قَلِيلَ الرَّدِّ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ تَذَاكَرْنَا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لَا تَنْقَطِعُ الْهِجْرَةُ حَتَّى تَنْقَطِعَ التَّوْبَةُ وَلَا تَنْقَطِعُ التَّوْبَةُ حَتَّى تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا ‏","","",""],[16302,16302,"","","‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ عِيسَى ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَوْرُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي عَوْنٍ ‏ ‏عَنْ ‏ ‏أَبِي إِدْرِيسَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُعَاوِيَةَ ‏ ‏وَكَانَ قَلِيلَ الْحَدِيثِ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَقُولُ ‏ ‏كُلُّ ذَنْبٍ عَسَى اللَّهُ أَنْ يَغْفِرَهُ إِلَّا الرَّجُلُ يَمُوتُ كَافِرًا أَوْ الرَّجُلُ يَقْتُلُ مُؤْمِنًا مُتَعَمِّدًا ‏","","",""],[16303,16303,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حُمْرَانَ بْنَ أَبَانَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ إِنَّكُمْ لَتُصَلُّونَ صَلَاةً لَقَدْ صَحِبْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَا رَأَيْنَاهُ يُصَلِّيهَا وَلَقَدْ ‏ ‏نَهَى عَنْهُمَا ‏ ‏يَعْنِي الرَّكْعَتَيْنِ بَعْدَ الْعَصْرِ ‏","","",""],[16304,16304,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي شَيْخٍ الْهُنَائِيِّ ‏ ‏أَنَّهُ شَهِدَ ‏ ‏مُعَاوِيَةَ ‏ ‏وَعِنْدَهُ جَمْعٌ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُمْ ‏ ‏مُعَاوِيَةُ ‏ ‏أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ رُكُوبِ جُلُودِ النُّمُورِ قَالُوا نَعَمْ قَالَ أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ لُبْسِ الْحَرِيرِ قَالُوا اللَّهُمَّ نَعَمْ قَالَ أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يُشْرَبَ فِي آنِيَةِ الْفِضَّةِ قَالُوا اللَّهُمَّ نَعَمْ قَالَ أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ لُبْسِ الذَّهَبِ إِلَّا مُقَطَّعًا قَالُوا اللَّهُمَّ نَعَمْ قَالَ أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ جَمْعٍ بَيْنَ حَجٍّ وَعُمْرَةٍ قَالُوا اللَّهُمَّ لَا قَالَ فَوَاللَّهِ إِنَّهَا لَمَعَهُنَّ ‏","","",""],[16305,16305,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَامِرٍ الْيَحْصَبِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏مُعَاوِيَةَ ‏ ‏يُحَدِّثُ وَهُوَ يَقُولُ إِيَّاكُمْ وَأَحَادِيثَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا حَدِيثًا كَانَ عَلَى عَهْدِ ‏ ‏عُمَرَ ‏ ‏وَإِنَّ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏كَانَ أَخَافَ النَّاسَ فِي اللَّهِ عَزَّ وَجَلَّ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ يُرِدْ اللَّهُ بِهِ خَيْرًا يُفَقِّهُّ فِي الدِّينِ وَسَمِعْتُهُ يَقُولُ إِنَّمَا أَنَا خَازِنٌ وَإِنَّمَا يُعْطِي اللَّهُ عَزَّ وَجَلَّ فَمَنْ أَعْطَيْتُهُ عَطَاءً عَنْ طِيبِ نَفْسٍ فَهُوَ أَنْ يُبَارَكَ لِأَحَدِكُمْ وَمَنْ أَعْطَيْتُهُ عَطَاءً عَنْ شَرَهٍ وَشَرَهِ مَسْأَلَةٍ فَهُوَ كَالْآكِلِ وَلَا يَشْبَعُ وَسَمِعْتُهُ يَقُولُ لَا تَزَالُ أُمَّةٌ مِنْ أُمَّتِي ظَاهِرِينَ عَنْ الْحَقِّ لَا يَضُرُّهُمْ مَنْ خَالَفَهُمْ حَتَّى يَأْتِيَ أَمْرُ اللَّهِ وَهُمْ ظَاهِرُونَ عَلَى النَّاسِ ‏","","",""],[16306,16306,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُمَرُ بْنُ عَطَاءِ بْنِ أَبِي الْخُوَارِ ‏ ‏أَنَّ ‏ ‏نَافِعَ بْنَ جُبَيْرٍ ‏ ‏أَرْسَلَهُ إِلَى ‏ ‏السَّائِبِ بْنِ يَزِيدَ ‏ ‏ابْنِ أُخْتِ ‏ ‏نَمِرٍ ‏ ‏يَسْأَلُهُ عَنْ شَيْءٍ رَآهُ مِنْهُ ‏ ‏مُعَاوِيَةُ ‏ ‏فِي الصَّلَاةِ قَالَ نَعَمْ صَلَّيْتُ مَعَهُ الْجُمُعَةَ فِي ‏ ‏الْمَقْصُورَةِ ‏ ‏فَلَمَّا سَلَّمَ قُمْتُ فِي مَقَامِي فَصَلَّيْتُ فَلَمَّا دَخَلَ أَرْسَلَ إِلَيَّ فَقَالَ لَا تَعُدْ لِمَا فَعَلْتَ إِذَا صَلَّيْتَ الْجُمُعَةَ فَلَا تَصِلْهَا بِصَلَاةٍ حَتَّى تَخْرُجَ أَوْ تَكَلَّمَ فَإِنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ بِذَلِكَ أَنْ ‏ ‏لَا تُوصَلَ صَلَاةٌ بِصَلَاةٍ حَتَّى تَخْرُجَ أَوْ تَكَلَّمَ ‏","","",""],[16307,16307,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حُمْرَانَ بْنَ أَبَانَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏أَنَّهُ رَأَى أُنَاسًا يُصَلُّونَ بَعْدَ الْعَصْرِ فَقَالَ إِنَّكُمْ لَتُصَلُّونَ صَلَاةً قَدْ صَحِبْنَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَا رَأَيْنَاهُ يُصَلِّيهَا وَلَقَدْ ‏ ‏نَهَى عَنْهَا ‏ ‏يَعْنِي الرَّكْعَتَيْنِ بَعْدَ الْعَصْرِ ‏","","",""],[16308,16308,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عُبَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏مُحَمَّدُ بْنُ يُوسُفَ ‏ ‏مَوْلَى ‏ ‏عَمْرِو بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ نَسِيَ شَيْئًا مِنْ صَلَاتِهِ فَلْيَسْجُدْ سَجْدَتَيْنِ وَهُوَ جَالِسٌ ‏","","",""],[16309,16309,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي الْفَيْضِ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[16310,16310,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ يَعْنِي ابْنَ عَجْلَانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يُوسُفَ ‏ ‏مَوْلَى ‏ ‏عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏يُوسُفَ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏أَنَّهُ صَلَّى أَمَامَهُمْ فَقَامَ فِي الصَّلَاةِ وَعَلَيْهِ جُلُوسٌ فَسَبَّحَ النَّاسُ فَتَمَّ عَلَى قِيَامِهِ ثُمَّ سَجَدْنَا سَجْدَتَيْنِ وَهُوَ جَالِسٌ بَعْدَ أَنْ أَتَمَّ الصَّلَاةَ ثُمَّ قَعَدَ عَلَى الْمِنْبَرِ فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ نَسِيَ مِنْ صَلَاتِهِ شَيْئًا فَلْيَسْجُدْ مِثْلَ هَاتَيْنِ السَّجْدَتَيْنِ ‏","","",""],[16311,16311,"","","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ مُعَاوِيَةَ الْفَزَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَبِيبُ بْنُ الشَّهِيدِ ‏ ‏عَنْ ‏ ‏أَبِي مِجْلَزٍ ‏ ‏قَالَ ‏ ‏خَرَجَ ‏ ‏مُعَاوِيَةُ ‏ ‏فَقَامُوا لَهُ فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ سَرَّهُ أَنْ ‏ ‏يَمْثُلَ ‏ ‏لَهُ الرِّجَالُ قِيَامًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[16312,16312,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏أَنَّ ‏ ‏سَعْدَ بْنَ إِبْرَاهِيمَ ‏ ‏أَخْبَرَهُ عَنِ ‏ ‏الْحَكَمِ بْنِ مِينَاءَ ‏ ‏أَنَّ ‏ ‏يَزِيدَ بْنَ جَارِيَةَ ‏ ‏أخْبَرَهُ ‏ ‏أَنَّهُ كَانَ جَالِسًا فِي نَفَرٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَخَرَجَ عَلَيْهِمْ ‏ ‏مُعَاوِيَةُ ‏ ‏فَسَأَلَهُمْ عَنْ حَدِيثِهِمْ فَقَالُوا كُنَّا فِي حَدِيثٍ مِنْ حَدِيثِ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏أَلَا أَزِيدُكُمْ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا بَلَى يَا أَمِيرَ الْمُؤْمِنِينَ فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَحَبَّ ‏ ‏الْأَنْصَارَ ‏ ‏أَحَبَّهُ اللَّهُ عَزَّ وَجَلَّ وَمَنْ أَبْغَضَ ‏ ‏الْأَنْصَارَ ‏ ‏أَبْغَضَهُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْحَكَمُ بْنُ مِينَاءَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ جَارِيَةَ ‏ ‏قَالَ ‏ ‏إِنِّي لَفِي مَجْلِسِ ‏ ‏مُعَاوِيَةَ ‏ ‏فِي نَفَرٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَنَحْنُ نَتَحَدَّثُ إِذْ خَرَجَ عَلَيْنَا ‏ ‏مُعَاوِيَةُ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[16313,16313,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَامِرٍ الْيَحْصَبِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُعَاوِيَةَ بْنَ أَبِي سُفْيَانَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّمَا أَنَا خَازِنٌ وَإِنَّمَا يُعْطِي اللَّهُ عَزَّ وَجَلَّ فَمَنْ أَعْطَيْتُهُ عَطَاءً بِطِيبِ نَفْسٍ فَإِنَّهُ يُبَارَكُ لَهُ فِيهِ وَمَنْ أَعْطَيْتُهُ عَطَاءً بِشَرَهِ نَفْسٍ وَشَرَهِ مَسْأَلَةٍ فَهُوَ كَالَّذِي يَأْكُلُ فَلَا يَشْبَعُ ‏","","",""],[16314,16314,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَذَّنَ الْمُؤَذِّنُ قَالَ مِثْلَ مَا يَقُولُ ‏","","",""],[16315,16315,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ سَعِيدٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ بْنِ عَلِيٍّ ‏ ‏أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏أَنَّهُ ‏ ‏سَمِعَ ‏ ‏مُعَاوِيَةَ ‏ ‏يَخْطُبُ فِي ظِلِّ ‏ ‏الْكَعْبَةِ ‏ ‏وَهُوَ يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ حُلِيِّ الذَّهَبِ وَلُبْسِ الْحَرِيرِ ‏","","",""],[16316,16316,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ بَهْدَلَةَ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا سَمِعَ الْمُؤَذِّنَ يَقُولُ ‏ ‏اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ قَالَ مِثْلَ قَوْلِهِ وَإِذَا قَالَ أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ قَالَ مِثْلَ قَوْلِهِ وَإِذَا قَالَ أَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ قَالَ مِثْلَ قَوْلِهِ ‏","","",""],[16317,16317,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا إِسْحَاقَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ الْبَجَلِيِّ ‏ ‏عَنْ ‏ ‏جَرِيرٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ ‏ ‏مُعَاوِيَةَ ‏ ‏يَخْطُبُ يَقُولُ ‏ ‏مَاتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ابْنُ ثَلَاثٍ وَسِتِّينَ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏وَهُوَ ابْنُ ثَلَاثٍ وَسِتِّينَ ‏ ‏وَعُمَرُ ‏ ‏وَهُوَ ابْنُ ثَلَاثٍ وَسِتِّينَ ‏ ‏وَأَنَا ابْنُ ثَلَاثٍ وَسِتِّينَ ‏","","",""],[16318,16318,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا شَرِبَ الْخَمْرَ فَاجْلِدُوهُ فَإِنْ عَادَ فَاجْلِدُوهُ فَإِنْ عَادَ فَاجْلِدُوهُ فَإِنْ عَادَ فَاقْتُلُوهُ ‏","","",""],[16319,16319,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُبَشِّرٍ ‏ ‏مَوْلَى ‏ ‏أُمِّ حَبِيبَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَبِي عَتَّابٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَيُّمَا امْرَأَةٍ أَدْخَلَتْ فِي شَعَرِهَا مِنْ شَعَرِ غَيْرِهَا فَإِنَّمَا تُدْخِلُهُ ‏ ‏زُورًا ‏","","",""],[16320,16320,"","","‏ ‏قَالَ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّاسُ تَبَعٌ ‏ ‏لِقُرَيْشٍ ‏ ‏فِي هَذَا الْأَمْرِ خِيَارُهُمْ فِي الْجَاهِلِيَّةِ خِيَارُهُمْ فِي الْإِسْلَامِ إِذَا فَقِهُوا وَاللَّهِ لَوْلَا أَنْ ‏ ‏تَبْطَرَ ‏ ‏قُرَيْشٌ ‏ ‏لَأَخْبَرْتُهَا مَا لِخِيَارِهَا عِنْدَ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[16321,16321,"","","‏ ‏قَالَ ‏ ‏وَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ وَلَا مُعْطِيَ لِمَا مَنَعْتَ وَلَا يَنْفَعُ ذَا ‏ ‏الْجَدِّ ‏ ‏مِنْكَ ‏ ‏الْجَدُّ ‏ ‏مَنْ يُرِدْ اللَّهُ بِهِ خَيْرًا يُفَقِّهُّ فِي الدِّينِ وَخَيْرُ نِسْوَةٍ رَكِبْنَ الْإِبِلَ صَالِحُ نِسَاءِ ‏ ‏قُرَيْشٍ ‏ ‏أَرْعَاهُ عَلَى زَوْجٍ فِي ذَاتِ يَدِهِ وَأَحْنَاهُ عَلَى وَلَدٍ فِي صِغَرِهِ ‏","","",""],[16322,16322,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُمَرُ بْنُ سَعِيدِ بْنِ أَبِي حُسَيْنٍ ‏ ‏أَنَّ ‏ ‏عَلِيَّ بْنَ عَبْدِ اللَّهِ بْنِ عَلِيٍّ الْعَدَوِيَّ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أَبَاهُ ‏ ‏أخْبَرَهُ قَالَ ‏ ‏سَمِعْتُ ‏ ‏مُعَاوِيَةَ ‏ ‏عَلَى الْمِنْبَرِ ‏ ‏بِمَكَّةَ ‏ ‏يَقُولُ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ لُبْسِ الذَّهَبِ وَالْحَرِيرِ ‏","","",""],[16323,16323,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْوَهَّابِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ يُرِدْ اللَّهُ بِهِ خَيْرًا يُفَقِّهُّ فِي الدِّينِ وَلَنْ تَزَالَ هَذِهِ الْأُمَّةُ أُمَّةً قَائِمَةً عَلَى أَمْرِ اللَّهِ لَا يَضُرُّهُمْ مَنْ خَالَفَهُمْ حَتَّى يَأْتِيَ أَمْرُ اللَّهِ وَهُمْ ظَاهِرُونَ عَلَى النَّاسِ ‏","","",""],[16324,16324,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمْزَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ بْنِ جَابِرٍ ‏ ‏أَنَّ ‏ ‏عُمَيْرَ بْنَ هَانِئٍ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏سَمِعْتُ ‏ ‏مُعَاوِيَةَ بْنَ أَبِي سُفْيَانَ ‏ ‏عَلَى هَذَا الْمِنْبَرِ يَقُولُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي قَائِمَةً بِأَمْرِ اللَّهِ لَا يَضُرُّهُمْ مَنْ خَذَلَهُمْ أَوْ خَالَفَهُمْ حَتَّى يَأْتِيَ أَمْرُ اللَّهِ عَزَّ وَجَلَّ وَهُمْ ظَاهِرُونَ عَلَى النَّاسِ ‏ ‏فَقَامَ ‏ ‏مَالِكُ بْنُ يَخَامِرٍ السَّكْسَكِيُّ ‏ ‏فَقَالَ ‏ ‏يَا أَمِيرَ الْمُؤْمِنِينَ ‏ ‏سَمِعْتُ ‏ ‏مُعَاذَ بْنَ جَبَلٍ ‏ ‏يَقُولُ ‏ ‏وَهُمْ أَهْلُ ‏ ‏الشَّامِ ‏ ‏فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏وَرَفَعَ صَوْتَهُ ‏ ‏هَذَا ‏ ‏مَالِكٌ ‏ ‏يَزْعُمُ أَنَّهُ سَمِعَ ‏ ‏مُعَاذًا ‏ ‏يَقُولُ وَهُمْ أَهْلُ ‏ ‏الشَّامِ ‏","","",""],[16325,16325,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو أُمَيَّةَ عَمْرُو بْنُ يَحْيَى بْنِ سَعِيدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَدِّي ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ ‏ ‏مُعَاوِيَةَ ‏ ‏أَخَذَ ‏ ‏الْإِدَاوَةَ ‏ ‏بَعْدَ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏يَتْبَعُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِهَا وَاشْتَكَى ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَبَيْنَا هُوَ يُوَضِّئُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَفَعَ رَأْسَهُ إِلَيْهِ مَرَّةً ‏ ‏أَوْ مَرَّتَيْنِ ‏ ‏فَقَالَ يَا ‏ ‏مُعَاوِيَةُ ‏ ‏إِنْ وُلِّيتَ أَمْرًا فَاتَّقِ اللَّهَ عَزَّ وَجَلَّ وَاعْدِلْ قَالَ فَمَا زِلْتُ أَظُنُّ أَنِّي ‏ ‏مُبْتَلًى ‏ ‏بِعَمَلٍ لِقَوْلِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى ‏ ‏ابْتُلِيتُ ‏","","",""],[16326,16326,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏قَالَ ‏ ‏قَدِمَ ‏ ‏مُعَاوِيَةُ بْنُ أَبِي سُفْيَانَ ‏ ‏الْمَدِينَةَ ‏ ‏وَكَانَتْ آخِرَ قَدْمَةٍ قَدِمَهَا ‏ ‏فَأَخْرَجَ ‏ ‏كُبَّةً ‏ ‏مِنْ شَعَرٍ فَقَالَ مَا كُنْتُ أَرَى أَنَّ أَحَدًا يَصْنَعُ هَذَا غَيْرَ ‏ ‏الْيَهُودِ ‏ ‏وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمَّاهُ ‏ ‏الزُّورَ ‏ ‏قَالَ كَأَنَّهُ ‏ ‏يَعْنِي ‏ ‏الْوِصَالَ ‏","","",""],[16327,16327,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عَيَّاشٍ يَعْنِي إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏وَغَيْرِهِ ‏ ‏عَنْ ‏ ‏أَبِي حَرِيزٍ ‏ ‏مَوْلَى ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ ‏ ‏خَطَبَ النَّاسَ ‏ ‏مُعَاوِيَةُ ‏ ‏بِحِمْصَ ‏ ‏فَذَكَرَ فِي خُطْبَتِهِ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَرَّمَ سَبْعَةَ أَشْيَاءَ وَإِنِّي أُبْلِغُكُمْ ذَلِكَ وَأَنْهَاكُمْ عَنْهُ مِنْهُنَّ ‏ ‏النَّوْحُ ‏ ‏وَالشِّعْرُ وَالتَّصَاوِيرُ وَالتَّبَرُّجُ وَجُلُودُ السِّبَاعِ وَالذَّهَبُ وَالْحَرِيرُ ‏","","",""],[16328,16328,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏صَفْوَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو الزَّاهِرِيَّةِ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّمَا أَنَا مُبَلِّغٌ وَاللَّهُ يَهْدِي وَقَاسِمٌ وَاللَّهُ يُعْطِي فَمَنْ بَلَغَهُ مِنِّي شَيْءٌ بِحُسْنِ رَغْبَةٍ وَحُسْنِ هُدًى فَإِنَّ ذَلِكَ الَّذِي يُبَارَكُ لَهُ فِيهِ ‏ ‏وَمَنْ بَلَغَهُ عَنِّي شَيْءٌ بِسُوءِ رَغْبَةٍ وَسُوءِ هُدًى فَذَاكَ الَّذِي يَأْكُلُ وَلَا يَشْبَعُ ‏","","",""],[16329,16329,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏صَفْوَانُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَزْهَرُ بْنُ عَبْدِ اللَّهِ الْهَوْزَنِيُّ ‏ ‏قَالَ ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏فِي مَوْضِعٍ آخَرَ ‏ ‏الْحَرَازِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عَامِرٍ عَبْدِ اللَّهِ بْنِ لُحَيٍّ ‏ ‏قَالَ ‏ ‏حَجَجْنَا مَعَ ‏ ‏مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ ‏ ‏فَلَمَّا قَدِمْنَا ‏ ‏مَكَّةَ ‏ ‏قَامَ حِينَ صَلَّى صَلَاةَ الظُّهْرِ فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ أَهْلَ الْكِتَابَيْنِ افْتَرَقُوا فِي دِينِهِمْ عَلَى ثِنْتَيْنِ وَسَبْعِينَ ‏ ‏مِلَّةً ‏ ‏وَإِنَّ هَذِهِ الْأُمَّةَ سَتَفْتَرِقُ عَلَى ثَلَاثٍ وَسَبْعِينَ ‏ ‏مِلَّةً ‏ ‏يَعْنِي الْأَهْوَاءَ ‏ ‏كُلُّهَا فِي النَّارِ إِلَّا وَاحِدَةً وَهِيَ الْجَمَاعَةُ وَإِنَّهُ سَيَخْرُجُ فِي أُمَّتِي أَقْوَامٌ ‏ ‏تَجَارَى ‏ ‏بِهِمْ تِلْكَ الْأَهْوَاءُ كَمَا ‏ ‏يَتَجَارَى ‏ ‏الْكَلْبُ ‏ ‏بِصَاحِبِهِ لَا يَبْقَى مِنْهُ عِرْقٌ وَلَا مَفْصِلٌ إِلَّا دَخَلَهُ وَاللَّهِ يَا مَعْشَرَ ‏ ‏الْعَرَبِ ‏ ‏لَئِنْ لَمْ تَقُومُوا بِمَا جَاءَ بِهِ نَبِيُّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَغَيْرُكُمْ مِنْ النَّاسِ ‏ ‏أَحْرَى ‏ ‏أَنْ لَا يَقُومَ بِهِ ‏","","",""],[16330,16330,"","","‏ ‏حَدَّثَنَا ‏ ‏مَرْوَانُ بْنُ شُجَاعٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏خُصَيْفٌ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏وَعَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏مُعَاوِيَةَ ‏ ‏أخْبَرَهُ ‏ ‏أَنَّهُ رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَصَّرَ مِنْ شَعَرِهِ ‏ ‏بِمِشْقَصٍ ‏ ‏فَقُلْتُ ‏ ‏لِابْنِ عَبَّاسٍ ‏ ‏مَا بَلَغَنَا هَذَا الْأَمْرُ إِلَّا عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏فَقَالَ مَا كَانَ ‏ ‏مُعَاوِيَةُ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُتَّهَمًا ‏","","",""],[16331,16331,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ عَبْدِ اللَّهِ بْنِ بَشَارٍ الْوَاسِطِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏وَأَبُو أَحْمَدَ ‏ ‏أَوْ أَحَدُهُمَا ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَصَّرَ ‏ ‏بِمِشْقَصٍ ‏","","",""],[16332,16332,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏تَمِيمٍ الدَّارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الدِّينَ النَّصِيحَةُ إِنَّمَا الدِّينُ النَّصِيحَةُ قَالُوا لِمَنْ يَا رَسُولَ اللَّهِ قَالَ لِلَّهِ وَلِكِتَابِهِ وَلِرَسُولِهِ وَلِأَئِمَّةِ الْمُسْلِمِينَ وَعَامَّتِهِمْ ‏","","",""],[16333,16333,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏تَمِيمٍ الدَّارِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّمَا الدِّينُ النَّصِيحَةُ قِيلَ لِمَنْ قَالَ لِلَّهِ وَلِرَسُولِهِ وَلِكِتَابِهِ وَلِأَئِمَّةِ الْمُسْلِمِينَ وَعَامَّتِهِمْ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏فَذَكَرَ مِثْلَهُ إِلَّا أَنَّهُ قَالَ إِنَّمَا الدِّينُ النَّصِيحَةُ ثَلَاثًا ‏","","",""],[16334,16334,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ أُسَامَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏خَرَجَ ‏ ‏عُمَرُ ‏ ‏عَلَى النَّاسِ يَضْرِبُهُمْ عَلَى السَّجْدَتَيْنِ بَعْدَ الْعَصْرِ حَتَّى مَرَّ ‏ ‏بِتَمِيمٍ الدَّارِيِّ ‏ ‏فَقَالَ لَا أَدَعُهُمَا ‏ ‏صَلَّيْتُهُمَا مَعَ مَنْ هُوَ خَيْرٌ مِنْكَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏إِنَّ النَّاسَ لَوْ كَانُوا ‏ ‏كَهَيْئَتِكَ ‏ ‏لَمْ أُبَالِ ‏","","",""],[16335,16335,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ الْأَزْرَقُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ مَوْهَبٍ ‏ ‏يُحَدِّثُ ‏ ‏عُمَرَ بْنَ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏تَمِيمٍ الدَّارِيِّ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الرَّجُلِ يُسْلِمُ عَلَى يَدَيْ الرَّجُلِ فَقَالَ هُوَ أَوْلَى النَّاسِ بِمَحْيَاهُ وَمَمَاتِهِ ‏","","",""],[16336,16336,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏تَمِيمٍ الدَّارِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الدِّينَ النَّصِيحَةُ إِنَّ الدِّينَ النَّصِيحَةُ إِنَّ الدِّينَ النَّصِيحَةُ قَالُوا لِمَنْ يَا رَسُولَ اللَّهِ قَالَ لِلَّهِ وَلِكِتَابِهِ وَلِنَبِيِّهِ وَلِأَئِمَّةِ الْمُؤْمِنِينَ وَعَامَّتِهِمْ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبَّادٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِسُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏فِي حَدِيثٍ ‏ ‏حَدَّثَنَاهُ ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنِ ‏ ‏الْقَعْقَاعِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏فَقَالَ ‏ ‏سُهَيْلٌ ‏ ‏سَمِعْتُهُ مِنْ الَّذِي سَمِعَهُ مِنْهُ أَبِي ‏ ‏سَمِعْتُ ‏ ‏عَطَاءَ بْنَ يَزِيدَ اللَّيْثِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏تَمِيمٍ الدَّارِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَ حَدِيثِ أَبِي عَنْ ‏ ‏ابْنِ عُيَيْنَةَ ‏","","",""],[16337,16337,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سُهَيْلِ بْنِ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏تَمِيمٍ الدَّارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الدِّينُ النَّصِيحَةُ الدِّينُ النَّصِيحَةُ ثَلَاثًا قَالُوا لِمَنْ يَا رَسُولَ اللَّهِ قَالَ لِلَّهِ وَلِكِتَابِهِ وَلِرَسُولِهِ وَلِأَئِمَّةِ الْمُسْلِمِينَ وَعَامَّتِهِمْ ‏","","",""],[16338,16338,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَوْهَبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏تَمِيمًا الدَّارِيَّ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏مَا السُّنَّةُ فِي الرَّجُلِ مِنْ ‏ ‏أَهْلِ الْكِتَابِ ‏ ‏يُسْلِمُ عَلَى يَدَيْ رَجُلٍ مِنْ الْمُسْلِمِينَ قَالَ هُوَ أَوْلَى النَّاسِ بِمَحْيَاهُ وَمَمَاتِهِ ‏","","",""],[16339,16339,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنِ ‏ ‏الْأَزْرَقِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ يَعْمَرَ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوَّلُ مَا يُحَاسَبُ بِهِ الْعَبْدُ يَوْمَ الْقِيَامَةِ صَلَاتُهُ فَإِنْ كَانَ أَتَمَّهَا كُتِبَتْ لَهُ تَامَّةً وَإِنْ لَمْ يَكُنْ أَتَمَّهَا قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏انْظُرُوا هَلْ تَجِدُونَ لِعَبْدِي مِنْ تَطَوُّعٍ فَتُكْمِلُونَ بِهَا فَرِيضَتَهُ ثُمَّ الزَّكَاةُ كَذَلِكَ ثُمَّ تُؤْخَذُ الْأَعْمَالُ عَلَى حِسَابِ ذَلِكَ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏زُرَارَةَ بْنِ أَوْفَى ‏ ‏عَنْ ‏ ‏تَمِيمٍ الدَّارِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏","","",""],[16340,16340,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى يَعْنِي الطَّبَّاعَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْخَلِيلُ بْنُ مُرَّةَ ‏ ‏عَنِ ‏ ‏الْأَزْهَرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏تَمِيمٍ الدَّارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَاحِدًا أَحَدًا صَمَدًا لَمْ يَتَّخِذْ صَاحِبَةً وَلَا وَلَدًا وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ عَشْرَ مَرَّاتٍ كُتِبَتْ لَهُ أَرْبَعُونَ أَلْفَ حَسَنَةٍ ‏","","",""],[16341,16341,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مَوْهَبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏تَمِيمًا الدَّارِيَّ ‏ ‏يَقُولُ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا السُّنَّةُ فِي ‏ ‏الرَّجُلِ مِنْ أَهْلِ الْكُفْرِ يُسْلِمُ عَلَى يَدَيْ الرَّجُلِ مِنْ الْمُسْلِمِينَ فَقَالَ هُوَ أَوْلَى النَّاسِ بِحَيَاتِهِ وَمَوْتِهِ ‏","","",""],[16342,16342,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏وَدَاوُدَ ‏ ‏عَنْ ‏ ‏زُرَارَةَ ‏ ‏عَنْ ‏ ‏تَمِيمٍ الدَّارِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَوَّلُ مَا يُحَاسَبُ بِهِ الْعَبْدُ يَوْمَ الْقِيَامَةِ الصَّلَاةُ فَإِنْ كَانَ أَكْمَلَهَا كُتِبَتْ لَهُ كَامِلَةً وَإِنْ لَمْ يَكُنْ أَكْمَلَهَا قَالَ لِلْمَلَائِكَةِ ‏ ‏انْظُرُوا هَلْ تَجِدُونَ لِعَبْدِي مِنْ تَطَوُّعٍ فَأَكْمِلُوا بِهَا مَا ضَيَّعَ مِنْ فَرِيضَةٍ ثُمَّ الزَّكَاةُ ثُمَّ تُؤْخَذُ الْأَعْمَالُ عَلَى حَسَبِ ذَلِكَ ‏","","",""],[16343,16343,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُرَحْبِيلُ بْنُ مُسْلِمٍ الْخَوْلَانِيُّ ‏ ‏أَنَّ ‏ ‏رَوْحَ بْنَ زِنْبَاعٍ ‏ ‏زَارَ ‏ ‏تَمِيمًا الدَّارِيَّ ‏ ‏فَوَجَدَهُ ‏ ‏يُنَقِّي شَعِيرًا لِفَرَسِهِ قَالَ وَحَوْلَهُ أَهْلُهُ فَقَالَ لَهُ ‏ ‏رَوْحٌ ‏ ‏أَمَا كَانَ فِي هَؤُلَاءِ مَنْ يَكْفِيكَ قَالَ ‏ ‏تَمِيمٌ ‏ ‏بَلَى وَلَكِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ امْرِئٍ مُسْلِمٍ ‏ ‏يُنَقِّي لِفَرَسِهِ شَعِيرًا ثُمَّ يُعَلِّقُهُ عَلَيْهِ إِلَّا كُتِبَ لَهُ بِكُلِّ حَبَّةٍ حَسَنَةٌ ‏ ‏حَدَّثَنَا ‏ ‏الْهَيْثَمُ بْنُ خَارِجَةَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏شُرَحْبِيلَ بْنِ مُسْلِمٍ ‏ ‏فَذَكَرَ مِثْلَ هَذَا الْحَدِيثِ ‏","","",""],[16344,16344,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ سُلَيْمٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سُلَيْمُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏تَمِيمٍ الدَّارِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَيَبْلُغَنَّ هَذَا الْأَمْرُ مَا بَلَغَ اللَّيْلُ وَالنَّهَارُ وَلَا يَتْرُكُ اللَّهُ بَيْتَ ‏ ‏مَدَرٍ ‏ ‏وَلَا ‏ ‏وَبَرٍ ‏ ‏إِلَّا أَدْخَلَهُ اللَّهُ هَذَا الدِّينَ بِعِزِّ عَزِيزٍ أَوْ بِذُلِّ ذَلِيلٍ عِزًّا يُعِزُّ اللَّهُ بِهِ الْإِسْلَامَ وَذُلًّا يُذِلُّ اللَّهُ بِهِ الْكُفْرَ ‏ ‏وَكَانَ ‏ ‏تَمِيمٌ الدَّارِيُّ ‏ ‏يَقُولُ ‏ ‏قَدْ عَرَفْتُ ذَلِكَ فِي أَهْلِ بَيْتِي لَقَدْ أَصَابَ مَنْ أَسْلَمَ مِنْهُمْ الْخَيْرُ وَالشَّرَفُ وَالْعِزُّ وَلَقَدْ أَصَابَ مَنْ كَانَ مِنْهُمْ كَافِرًا الذُّلُّ وَالصَّغَارُ ‏ ‏وَالْجِزْيَةُ ‏","","",""],[16345,16345,"","","‏ ‏أَمْلَاهُ عَلَيْنَا مِنْ النَّوَادِرِ ‏ ‏قَالَ كَتَبَ إِلَيَّ ‏ ‏أَبُو تَوْبَةَ الرَّبِيعُ بْنُ نَافِعٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْهَيْثَمُ بْنُ حُمَيْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَاقِدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏تَمِيمٍ الدَّارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَرَأَ بِمِائَةِ آيَةٍ فِي لَيْلَةٍ كُتِبَ لَهُ ‏ ‏قُنُوتُ ‏ ‏لَيْلَةٍ ‏","","",""],[16346,16346,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏أَبِي أَيُّوبَ ‏ ‏عَنْ ‏ ‏مَسْلَمَةَ بْنِ مُخَلَّدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ سَتَرَ مُسْلِمًا فِي الدُّنْيَا سَتَرَهُ اللَّهُ عَزَّ وَجَلَّ فِي الدُّنْيَا وَالْآخِرَةِ وَمَنْ نَجَّى ‏ ‏مَكْرُوبًا ‏ ‏فَكَّ اللَّهُ عَنْهُ ‏ ‏كُرْبَةً ‏ ‏مِنْ ‏ ‏كُرَبِ ‏ ‏يَوْمِ الْقِيَامَةِ وَمَنْ كَانَ فِي حَاجَةِ أَخِيهِ كَانَ اللَّهُ عَزَّ وَجَلَّ فِي حَاجَتِهِ ‏","","",""],[16347,16347,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏أَبِي هَذَا الْحَدِيثَ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ ‏ ‏وَابْنُ أَبِي عَدِيٍّ ‏ ‏عَنِ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏أَنَّ ‏ ‏عُقْبَةَ ‏ ‏قَالَ ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏أَتَى ‏ ‏مَسْلَمَةَ بْنَ مُخَلَّدٍ ‏ ‏بِمِصْرَ ‏ ‏وَكَانَ بَيْنَهُ وَبَيْنَ الْبَوَّابِ شَيْءٌ فَسَمِعَ صَوْتَهُ فَأَذِنَ لَهُ فَقَالَ إِنِّي لَمْ آتِكَ زَائِرًا وَلَكِنِّي جِئْتُكَ لِحَاجَةٍ أَتَذْكُرُ يَوْمَ ‏ ‏قَالَ ‏ ‏عَبَّادٌ ‏ ‏فِي حَدِيثِهِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ عَلِمَ مِنْ أَخِيهِ سَيِّئَةً فَسَتَرَهَا سَتَرَهُ اللَّهُ عَزَّ وَجَلَّ بِهَا يَوْمَ الْقِيَامَةِ فَقَالَ نَعَمْ فَقَالَ لِهَذَا جِئْتُ ‏ ‏قَالَ ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏فِي حَدِيثِهِ رَكِبَ ‏ ‏عُقْبَةُ بْنُ عَامِرٍ ‏ ‏إِلَى ‏ ‏مَسْلَمَةَ بْنِ مُخَلَّدٍ ‏ ‏وَهُوَ أَمِيرٌ عَلَى ‏ ‏مِصْرَ ‏","","",""],[16348,16348,"","","‏ ‏قَالَ ‏ ‏حُسَيْنُ بْنُ عَلِيٍّ الْجُعْفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏بِهِ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ يَزِيدَ بْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ الصَّنْعَانِيِّ ‏ ‏عَنْ ‏ ‏أَوْسِ بْنِ أَوْسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ غَسَّلَ وَاغْتَسَلَ وَغَدَا وَابْتَكَرَ فَدَنَا وَأَنْصَتَ وَلَمْ ‏ ‏يَلْغُ ‏ ‏كَانَ لَهُ بِكُلِّ خُطْوَةٍ كَأَجْرِ سَنَةٍ صِيَامِهَا وَقِيَامِهَا ‏","","",""],[16349,16349,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنِ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏حَسَّانَ بْنِ عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ الصَّنْعَانِيِّ ‏ ‏عَنْ ‏ ‏أَوْسِ بْنِ أَوْسٍ الثَّقَفِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ غَسَّلَ وَاغْتَسَلَ يَوْمَ الْجُمُعَةِ وَبَكَّرَ وَابْتَكَرَ وَمَشَى وَلَمْ يَرْكَبْ فَدَنَا مِنْ الْإِمَامِ وَاسْتَمَعَ وَلَمْ ‏ ‏يَلْغُ ‏ ‏كَانَ لَهُ بِكُلِّ خُطْوَةٍ أَجْرُ سَنَةٍ صِيَامِهَا وَقِيَامِهَا ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنِ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏حَدَّثَنِي ‏ ‏حَسَّانُ بْنُ عَطِيَّةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَشْعَثِ الصَّنْعَانِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ أَوْسٍ الثَّقَفِيُّ ‏ ‏قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ إِلَّا أَنَّهُ قَالَ ثُمَّ غَدَا وَابْتَكَرَ ‏","","",""],[16350,16350,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَرْطَاةُ يَعْنِي ابْنَ الْمُنْذِرِ ‏ ‏حَدَّثَنَا ‏ ‏ضَمْرَةُ بْنُ حَبِيبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَلَمَةُ بْنُ نُفَيْلٍ السَّكُونِيُّ ‏ ‏قَالَ ‏ ‏كُنَّا جُلُوسًا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ قَالَ لَهُ قَائِلٌ يَا رَسُولَ اللَّهِ هَلْ أُتِيتَ بِطَعَامٍ مِنْ السَّمَاءِ قَالَ نَعَمْ قَالَ وَبِمَاذَا قَالَ ‏ ‏بِمِسْخَنَةٍ ‏ ‏قَالُوا فَهَلْ كَانَ فِيهَا ‏ ‏فَضْلٌ ‏ ‏عَنْكَ قَالَ نَعَمْ قَالَ فَمَا فُعِلَ بِهِ قَالَ رُفِعَ وَهُوَ يُوحَى إِلَيَّ ‏ ‏أَنِّي ‏ ‏مَكْفُوتٌ ‏ ‏غَيْرُ ‏ ‏لَابِثٍ ‏ ‏فِيكُمْ وَلَسْتُمْ ‏ ‏لَابِثِينَ ‏ ‏بَعْدِي إِلَّا قَلِيلًا بَلْ ‏ ‏تَلْبَثُونَ ‏ ‏حَتَّى تَقُولُوا مَتَى وَسَتَأْتُونَ ‏ ‏أَفْنَادًا ‏ ‏يُفْنِي بَعْضُكُمْ بَعْضًا وَبَيْنَ يَدَيْ السَّاعَةِ ‏ ‏مُوتَانٌ شَدِيدٌ وَبَعْدَهُ سَنَوَاتُ الزَّلَازِلِ ‏","","",""],[16351,16351,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ سُلَيْمَانَ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ عَبْدِ الرَّحْمَنِ الْجُرَشِيِّ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏أَنَّ ‏ ‏سَلَمَةَ بْنَ نُفَيْلٍ ‏ ‏أَخْبَرَهُمْ ‏ ‏أَنَّهُ أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنِّي سَئِمْتُ الْخَيْلَ وَأَلْقَيْتُ السِّلَاحَ وَوَضَعَتْ الْحَرْبُ ‏ ‏أَوْزَارَهَا ‏ ‏قُلْتُ لَا قِتَالَ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْآنَ جَاءَ الْقِتَالُ ‏ ‏لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي ظَاهِرِينَ عَلَى النَّاسِ يَرْفَعُ اللَّهُ قُلُوبَ أَقْوَامٍ فَيُقَاتِلُونَهُمْ وَيَرْزُقُهُمْ اللَّهُ مِنْهُمْ حَتَّى يَأْتِيَ أَمْرُ اللَّهِ عَزَّ وَجَلَّ وَهُمْ عَلَى ذَلِكَ أَلَا إِنَّ ‏ ‏عُقْرَ ‏ ‏دَارِ الْمُؤْمِنِينَ ‏ ‏الشَّامُ ‏ ‏وَالْخَيْلُ ‏ ‏مَعْقُودٌ ‏ ‏فِي نَوَاصِيهَا الْخَيْرُ إِلَى يَوْمِ الْقِيَامَةِ ‏","","",""],[16352,16352,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏قَالَ ‏ ‏كَتَبَ إِلَيَّ ‏ ‏أَبُو تَوْبَةَ الرَّبِيعُ بْنُ نَافِعٍ ‏ ‏وَكَانَ فِي كِتَابِهِ ‏ ‏حَدَّثَنَا ‏ ‏الْهَيْثَمُ بْنُ حُمَيْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَاقِدٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الْأَخْنَسِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَنَافُسَ بَيْنَكُمْ إِلَّا فِي اثْنَتَيْنِ رَجُلٌ أَعْطَاهُ اللَّهُ عَزَّ وَجَلَّ الْقُرْآنَ فَهُوَ يَقُومُ بِهِ آنَاءَ اللَّيْلِ وَآنَاءَ النَّهَارِ وَيَتَّبِعُ مَا فِيهِ فَيَقُولُ رَجُلٌ لَوْ أَنَّ اللَّهَ تَعَالَى أَعْطَانِي مِثْلَ مَا أَعْطَى فُلَانًا فَأَقُومَ بِهِ كَمَا يَقُومُ بِهِ وَرَجُلٌ أَعْطَاهُ اللَّهُ مَالًا فَهُوَ يُنْفِقُ وَيَتَصَدَّقُ فَيَقُولُ رَجُلٌ لَوْ أَنَّ اللَّهَ أَعْطَانِي مِثْلَ مَا أَعْطَى فُلَانًا فَأَتَصَدَّقَ بِهِ فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ أَرَأَيْتُكَ ‏ ‏النَّجْدَةَ ‏ ‏تَكُونُ فِي الرَّجُلِ وَسَقَطَ بَاقِي الْحَدِيثِ ‏","","",""],[16353,16353,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ سَيْفٍ ‏ ‏عَنْ ‏ ‏غُضَيْفِ بْنِ الْحَارِثِ ‏ ‏أَوْ ‏ ‏الْحَارِثِ بْنِ غُضَيْفٍِ ‏ ‏قَالَ ‏ ‏مَا نَسِيتُ مِنْ الْأَشْيَاءِ مَا نَسِيتُ أَنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاضِعًا يَمِينَهُ عَلَى شِمَالِهِ فِي الصَّلَاةِ ‏","","",""],[16354,16354,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ سَيْفٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ غُضَيْفٍ ‏ ‏أَوْ ‏ ‏غُضَيْفِ بْنِ الْحَارِثِ ‏ ‏قَالَ ‏ ‏مَا نَسِيتُ مِنْ الْأَشْيَاءِ لَمْ أَنْسَ أَنِّي رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاضِعًا يَمِينَهُ عَلَى شِمَالِهِ فِي الصَّلَاةِ ‏","","",""],[16355,16355,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ ‏ ‏حَدَّثَنِي ‏ ‏الْمَشْيَخَةُ ‏ ‏أَنَّهُمْ حَضَرُوا ‏ ‏غُضَيْفَ بْنَ الْحَارِثِ الثُّمَالِيَّ ‏ ‏حِينَ اشْتَدَّ ‏ ‏سَوْقُهُ ‏ ‏فَقَالَ ‏ ‏هَلْ مِنْكُمْ أَحَدٌ يَقْرَأُ ‏ ‏يس ‏ ‏قَالَ فَقَرَأَهَا ‏ ‏صَالِحُ بْنُ شُرَيْحٍ السَّكُونِيُّ ‏ ‏فَلَمَّا بَلَغَ أَرْبَعِينَ مِنْهَا قُبِضَ قَالَ فَكَانَ ‏ ‏الْمَشْيَخَةُ ‏ ‏يَقُولُونَ إِذَا قُرِئَتْ عِنْدَ الْمَيِّتِ خُفِّفَ عَنْهُ بِهَا ‏ ‏قَالَ ‏ ‏صَفْوَانُ ‏ ‏وَقَرَأَهَا ‏ ‏عِيسَى بْنُ الْمُعْتَمِرِ ‏ ‏عِنْدَ ‏ ‏ابْنِ مَعْبَدٍ ‏","","",""],[16356,16356,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ عُبَيْدٍ الرَّحَبِيِّ ‏ ‏عَنْ ‏ ‏غُضَيْفِ بْنِ الْحَارِثِ الثُّمَالِيِّ ‏ ‏قَالَ ‏ ‏بَعَثَ إِلَيَّ ‏ ‏عَبْدُ الْمَلِكِ بْنُ مَرْوَانَ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا أَسْمَاءَ ‏ ‏إِنَّا قَدْ أَجْمَعْنَا النَّاسَ عَلَى أَمْرَيْنِ قَالَ وَمَا هُمَا قَالَ رَفْعُ الْأَيْدِي عَلَى الْمَنَابِرِ يَوْمَ الْجُمُعَةِ وَالْقَصَصُ بَعْدَ الصُّبْحِ وَالْعَصْرِ فَقَالَ أَمَا إِنَّهُمَا أَمْثَلُ بِدْعَتِكُمْ عِنْدِي وَلَسْتُ مُجِيبَكَ إِلَى شَيْءٍ مِنْهُمَا قَالَ لِمَ قَالَ لِأَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا أَحْدَثَ قَوْمٌ بِدْعَةً إِلَّا رُفِعَ مِثْلُهَا مِنْ السُّنَّةِ فَتَمَسُّكٌ بِسُنَّةٍ خَيْرٌ مِنْ إِحْدَاثِ بِدْعَةٍ ‏","","",""],[16357,16357,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏حَرِيزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُرَحْبِيلُ ابْنُ شُفْعَةَ ‏ ‏عَنْ ‏ ‏بَعْضِ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ يُقَالُ لِلْوِلْدَانِ يَوْمَ الْقِيَامَةِ ادْخُلُوا الْجَنَّةَ قَالَ فَيَقُولُونَ يَا رَبِّ حَتَّى يَدْخُلَ آبَاؤُنَا ‏ ‏وَأُمَّهَاتُنَا قَالَ فَيَأْتُونَ قَالَ فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏مَا لِي أَرَاهُمْ ‏ ‏مُحْبَنْطِئِينَ ‏ ‏ادْخُلُوا الْجَنَّةَ قَالَ فَيَقُولُونَ يَا رَبِّ آبَاؤُنَا ‏ ‏وَأُمَّهَاتُنَا قَالَ فَيَقُولُ ادْخُلُوا الْجَنَّةَ أَنْتُمْ وَآبَاؤُكُمْ ‏","","",""],[16358,16358,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏حَرِيزُ بْنُ عُثْمَانَ الرَّحَبِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَامِرٍ الْأَلْهَانِيَّ ‏ ‏قَالَ ‏ ‏دَخَلَ الْمَسْجِدَ ‏ ‏حَابِسُ بْنُ سَعْدٍ الطَّائِيُّ ‏ ‏مِنْ ‏ ‏السَّحَرِ ‏ ‏وَقَدْ أَدْرَكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَأَى النَّاسَ يُصَلُّونَ فِي مُقَدَّمِ الْمَسْجِدِ فَقَالَ ‏ ‏مُرَاءُونَ ‏ ‏وَرَبِّ ‏ ‏الْكَعْبَةِ ‏ ‏أَرْعِبُوهُمْ فَمَنْ أَرْعَبَهُمْ فَقَدْ أَطَاعَ اللَّهَ وَرَسُولَهُ فَأَتَاهُمْ النَّاسُ فَأَخْرَجُوهُمْ قَالَ فَقَالَ إِنَّ الْمَلَائِكَةَ يُصَلُّونَ مِنْ ‏ ‏السَّحَرِ ‏ ‏فِي مُقَدَّمِ الْمَسْجِدِ ‏","","",""],[16359,16359,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَيُّوبَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ لَقِيطٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ حَوَالَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ نَجَا مِنْ ثَلَاثٍ فَقَدْ نَجَا ثَلَاثَ مَرَّاتٍ ‏ ‏مَوْتِي ‏ ‏وَالدَّجَّالُ ‏ ‏وَقَتْلُ خَلِيفَةٍ مُصْطَبِرٍ بِالْحَقِّ مُعْطِيهِ ‏","","",""],[16360,16360,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ حِمْيَرٍ الْحِمْصِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ثَابِتُ بْنُ عَجْلَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا كَثِيرٍ الْمُحَارِبِيَّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏خَرَشَةَ بْنَ الْحُرِّ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏سَتَكُونُ مِنْ بَعْدِي فِتْنَةٌ النَّائِمُ فِيهَا خَيْرٌ مِنْ الْيَقْظَانِ وَالْقَاعِدُ فِيهَا خَيْرٌ مِنْ الْقَائِمِ وَالْقَائِمُ فِيهَا خَيْرٌ مِنْ السَّاعِي فَمَنْ أَتَتْ عَلَيْهِ فَلْيَمْشِ بِسَيْفِهِ إِلَى ‏ ‏صَفَاةٍ ‏ ‏فَلْيَضْرِبْهُ حَتَّى يَنْكَسِرَ ثُمَّ لِيَضْطَجِعَ لَهَا حَتَّى ‏ ‏تَنْجَلِيَ ‏ ‏عَمَّا ‏ ‏انْجَلَيَتْ ‏","","",""],[16361,16361,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَزِيدَ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عَوْفٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أَبَا جُمُعَةَ حَبِيبَ بْنِ سِبَاعٍ ‏ ‏وَكَانَ قَدْ أَدْرَكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَ الْأَحْزَابِ صَلَّى الْمَغْرِبَ فَلَمَّا فَرَغَ قَالَ هَلْ عَلِمَ أَحَدٌ مِنْكُمْ أَنِّي صَلَّيْتُ الْعَصْرَ قَالُوا يَا رَسُولَ اللَّهِ مَا صَلَّيْتَهَا ‏ ‏فَأَمَرَ الْمُؤَذِّنَ فَأَقَامَ الصَّلَاةَ فَصَلَّى الْعَصْرَ ثُمَّ أَعَادَ الْمَغْرِبَ ‏","","",""],[16362,16362,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَسِيدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏صَالِحٌ أَبُو مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو جُمُعَةَ ‏ ‏قَالَ تَغَدَّيْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَعَنَا ‏ ‏أَبُو عُبَيْدَةَ بْنُ الْجَرَّاحِ ‏ ‏قَالَ فَقَالَ يَا رَسُولَ اللَّهِ هَلْ أَحَدٌ خَيْرٌ مِنَّا أَسْلَمْنَا مَعَكَ وَجَاهَدْنَا مَعَكَ قَالَ ‏ ‏نَعَمْ قَوْمٌ يَكُونُونَ مِنْ بَعْدِكُمْ يُؤْمِنُونَ بِي وَلَمْ يَرَوْنِي ‏","","",""],[16363,16363,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَسِيدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ دُرَيْكٍ ‏ ‏عَنْ ‏ ‏أَبِي مُحَيْرِيزٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِأَبِي جُمُعَةَ ‏ ‏رَجُلٍ مِنْ الصَّحَابَةِ حَدِّثْنَا حَدِيثًا سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ أُحَدِّثُكُمْ حَدِيثًا جَيِّدًا تَغَدَّيْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَعَنَا ‏ ‏أَبُو عُبَيْدَةَ بْنُ الْجَرَّاحِ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَحَدٌ خَيْرٌ مِنَّا أَسْلَمْنَا مَعَكَ وَجَاهَدْنَا مَعَكَ قَالَ ‏ ‏نَعَمْ قَوْمٌ يَكُونُونَ مِنْ بَعْدِكُمْ يُؤْمِنُونَ بِي وَلَمْ يَرَوْنِي ‏","","",""],[16364,16364,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْأَوْزَاعِيَّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَبِيعَةُ بْنُ يَزِيدَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏وَاثِلَةَ بْنَ الْأَسْقَعِ ‏ ‏يَقُولُ ‏ ‏خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَتَزْعُمُونَ ‏ ‏أَنِّي آخِرِكُمْ ‏ ‏وَفَاةً أَلَا إِنِّي مِنْ أَوَّلِكُمْ وَفَاةً وَتَتْبَعُونِي ‏ ‏أَفْنَادًا ‏ ‏يُهْلِكُ بَعْضُكُمْ بَعْضًا ‏","","",""],[16365,16365,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ الْغَازِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ ‏ ‏دَعَانِي ‏ ‏وَاثِلَةُ بْنُ الْأَسْقَعِ ‏ ‏وَقَدْ ذَهَبَ بَصَرُهُ فَقَالَ يَا ‏ ‏خَبَّابُ ‏ ‏قُدْنِي إِلَى ‏ ‏يَزِيدَ بْنِ الْأَسْوَدِ الْجُرَشِيِّ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏فَقَالَ أَبْشِرْ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ عَنْ اللَّهِ عَزَّ وَجَلَّ ‏ ‏أَنَا عِنْدَ ظَنِّ عَبْدِي بِي فَلْيَظُنَّ بِي مَا شَاءَ ‏","","",""],[16366,16366,"","","‏ ‏حَدَّثَنَا ‏ ‏عِصَامُ بْنُ خَالِدٍ ‏ ‏وَأَبُو الْمُغِيرَةِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَرِيزُ بْنُ عُثْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الْوَاحِدِ بْنَ عَبْدِ اللَّهِ النَّصْرِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏وَاثِلَةَ بْنَ الْأَسْقَعِ ‏ ‏يَقُولُ ‏ ‏قَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِنْ أَعْظَمِ ‏ ‏الْفِرَى ‏ ‏أَنْ يُدْعَى الرَّجُلُ إِلَى غَيْرِ أَبِيهِ أَوْ يُرِيَ عَيْنَيْهِ فِي الْمَنَامِ مَا لَمْ تَرَيَا أَوْ يَقُولَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا لَمْ يَقُلْ ‏","","",""],[16367,16367,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ رَبِّهِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ حَرْبٍ الْخَوْلَانِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُمَرُ بْنُ رُؤْبَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الْوَاحِدِ النَّصْرِيَّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏وَاثِلَةَ بْنَ الْأَسْقَعِ ‏ ‏يَذْكُرُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمَرْأَةُ تَحُوزُ ثَلَاثَةَ مَوَارِيثَ عَتِيقَهَا وَلَقِيطَهَا وَالْوَلَدَ الَّذِي ‏ ‏لَاعَنَتْ ‏ ‏عَلَيْهِ ‏","","",""],[16368,16368,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ أَبُو دَاوُدَ الطَّيَالِسِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عِمْرَانُ الْقَطَّانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ الْهُذَلِيِّ ‏ ‏عَنْ ‏ ‏وَاثِلَةَ بْنِ الْأَسْقَعِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أُعْطِيتُ مَكَانَ التَّوْرَاةِ السَّبْعَ وَأُعْطِيتُ مَكَانَ الزَّبُورِ ‏ ‏الْمَئِينَ ‏ ‏وَأُعْطِيتُ مَكَانَ الْإِنْجِيلِ ‏ ‏الْمَثَانِيَ ‏ ‏وَفُضِّلْتُ ‏ ‏بِالْمُفَصَّلِ ‏","","",""],[16369,16369,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي أَيُّوبَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَجْلَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏النَّضْرَ بْنَ عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏وَاثِلَةَ بْنَ الْأَسْقَعِ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْظَمُ ‏ ‏الْفِرَى ‏ ‏مَنْ يُقَوِّلُنِي مَا لَمْ أَقُلْ وَمَنْ أَرَى عَيْنَيْهِ فِي الْمَنَامِ مَا لَمْ تَرَيَا وَمَنْ ادَّعَى إِلَى غَيْرِ أَبِيهِ ‏","","",""],[16370,16370,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عِمْرَانُ أَبُو الْعَوَّامِ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏عَنْ ‏ ‏وَاثِلَةَ بْنِ الْأَسْقَعِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أُنْزِلَتْ صُحُفُ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فِي أَوَّلِ لَيْلَةٍ مِنْ رَمَضَانَ وَأُنْزِلَتْ التَّوْرَاةُ لِسِتٍّ مَضَيْنَ مِنْ رَمَضَانَ وَالْإِنْجِيلُ لِثَلَاثَ عَشْرَةَ خَلَتْ مِنْ رَمَضَانَ وَأُنْزِلَ الْفُرْقَانُ لِأَرْبَعٍ وَعِشْرِينَ خَلَتْ مِنْ رَمَضَانَ ‏","","",""],[16371,16371,"","","‏ ‏حَدَّثَنَا ‏ ‏عَارِمُ بْنُ الْفَضْلِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ أَبِي عَبْلَةَ ‏ ‏عَنِ ‏ ‏الْغَرِيفِ بْنِ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏وَاثِلَةَ بْنِ الْأَسْقَعِ ‏ ‏قَالَ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَفَرٌ مِنْ ‏ ‏بَنِي سُلَيْمٍ ‏ ‏فَقَالُوا ‏ ‏إِنَّ صَاحِبًا لَنَا ‏ ‏أَوْجَبَ ‏ ‏قَالَ فَلْيُعْتِقْ رَقَبَةً ‏ ‏يَفْدِي اللَّهُ بِكُلِّ عُضْوٍ مِنْهَا عُضْوًا مِنْهُ مِنْ النَّارِ ‏","","",""],[16372,16372,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو عَمَّارٍ شَدَّادٌ ‏ ‏عَنْ ‏ ‏وَاثِلَةَ بْنِ الْأَسْقَعِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ اصْطَفَى ‏ ‏كِنَانَةَ ‏ ‏مِنْ ‏ ‏بَنِي إِسْمَاعِيلَ ‏ ‏وَاصْطَفَى مِنْ ‏ ‏بَنِي كِنَانَةَ ‏ ‏قُرَيْشًا ‏ ‏وَاصْطَفَى مِنْ ‏ ‏قُرَيْشٍ ‏ ‏بَنِي هَاشِمٍ ‏ ‏وَاصْطَفَانِي مِنْ ‏ ‏بَنِي هَاشِمٍ ‏","","",""],[16373,16373,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏شَدَّادٍ أَبِي عَمَّارٍ ‏ ‏عَنْ ‏ ‏وَاثِلَةَ بْنِ الْأَسْقَعِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ اصْطَفَى مِنْ وَلَدِ ‏ ‏إِبْرَاهِيمَ ‏ ‏إِسْمَاعِيلَ ‏ ‏وَاصْطَفَى مِنْ ‏ ‏بَنِي إِسْمَاعِيلَ ‏ ‏كِنَانَةَ ‏ ‏وَاصْطَفَى مِنْ ‏ ‏بَنِي كِنَانَةَ ‏ ‏قُرَيْشًا ‏ ‏وَاصْطَفَى مِنْ ‏ ‏قُرَيْشٍ ‏ ‏بَنِي هَاشِمٍ ‏ ‏وَاصْطَفَانِي مِنْ ‏ ‏بَنِي هَاشِمٍ ‏","","",""],[16374,16374,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏شَدَّادٍ أَبِي عَمَّارٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏وَاثِلَةَ بْنِ الْأَسْقَعِ ‏ ‏وَعِنْدَهُ قَوْمٌ فَذَكَرُوا ‏ ‏عَلِيًّا ‏ ‏فَلَمَّا قَامُوا قَالَ لِي أَلَا أُخْبِرُكَ بِمَا رَأَيْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ بَلَى قَالَ أَتَيْتُ ‏ ‏فَاطِمَةَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهَا ‏ ‏أَسْأَلُهَا عَنْ ‏ ‏عَلِيٍّ ‏ ‏قَالَتْ تَوَجَّهَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَلَسْتُ أَنْتَظِرُهُ حَتَّى جَاءَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَعَهُ ‏ ‏عَلِيٌّ ‏ ‏وَحَسَنٌ ‏ ‏وَحُسَيْنٌ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمْ ‏ ‏آخِذٌ كُلَّ وَاحِدٍ مِنْهُمَا بِيَدِهِ حَتَّى دَخَلَ ‏ ‏فَأَدْنَى ‏ ‏عَلِيًّا ‏ ‏وَفَاطِمَةَ ‏ ‏فَأَجْلَسَهُمَا بَيْنَ يَدَيْهِ وَأَجْلَسَ ‏ ‏حَسَنًا ‏ ‏وَحُسَيْنًا ‏ ‏كُلَّ وَاحِدٍ مِنْهُمَا عَلَى فَخِذِهِ ثُمَّ لَفَّ عَلَيْهِمْ ثَوْبَهُ ‏ ‏أَوْ قَالَ كِسَاءً ‏ ‏ثُمَّ تَلَا هَذِهِ الْآيَةَ ‏ { ‏إِنَّمَا يُرِيدُ اللَّهُ لِيُذْهِبَ عَنْكُمْ الرِّجْسَ أَهْلَ ‏ ‏الْبَيْتِ ‏ ‏وَيُطَهِّرَكُمْ تَطْهِيرًا ‏} ‏وَقَالَ اللَّهُمَّ هَؤُلَاءِ أَهْلُ بَيْتِي وَأَهْلُ بَيْتِي أَحَقُّ ‏","","",""],[16375,16375,"","","‏ ‏حَدَّثَنَا ‏ ‏زِيَادُ بْنُ الرَّبِيعِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ كَثِيرٍ الشَّامِيُّ ‏ ‏مِنْ أَهْلِ ‏ ‏فِلَسْطِينَ ‏ ‏عَنِ ‏ ‏امْرَأَةٍ مِنْهُمْ يُقَالُ لَهَا ‏ ‏فَسِيلَةُ ‏ ‏أَنَّهَا قَالَتْ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يَقُولُ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ أَمِنَ ‏ ‏الْعَصَبِيَّةِ ‏ ‏أَنْ يُحِبَّ الرَّجُلُ قَوْمَهُ قَالَ ‏ ‏لَا وَلَكِنْ مِنْ ‏ ‏الْعَصَبِيَّةِ ‏ ‏أَنْ يَنْصُرَ الرَّجُلُ قَوْمَهُ عَلَى الظُّلْمِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏سَمِعْتُ مَنْ يَذْكُرُ مِنْ أَهْلِ الْعِلْمِ أَنَّ أَبَاهَا ‏ ‏يَعْنِي ‏ ‏فَسِيلَةَ ‏ ‏وَاثِلَةُ بْنُ الْأَسْقَعِ ‏ ‏وَرَأَيْتُ أَبِي جَعَلَ هَذَا الْحَدِيثَ فِي آخِرِ أَحَادِيثِ ‏ ‏وَاثِلَةَ ‏ ‏فَظَنَنْتُ أَنَّهُ أَلْحَقَهُ فِي حَدِيثِ ‏ ‏وَاثِلَةَ ‏","","",""],[16376,16376,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا بْنِ أَبِي زَائِدَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي مَرْزُوقٍ ‏ ‏مَوْلَى ‏ ‏تُجِيبَ ‏ ‏وَتُجِيبُ ‏ ‏بَطْنٌ مِنْ ‏ ‏كِنْدَةَ ‏ ‏عَنْ ‏ ‏رُوَيْفِعِ بْنِ ثَابِتٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏كُنْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ افْتَتَحَ ‏ ‏حُنَيْنًا ‏ ‏فَقَامَ فِينَا خَطِيبًا فَقَالَ ‏ ‏لَا يَحِلُّ لِامْرِئٍ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ أَنْ يَسْقِيَ مَاءَهُ زَرْعَ غَيْرِهِ وَلَا أَنْ يَبْتَاعَ مَغْنَمًا حَتَّى يُقْسَمَ وَلَا أَنْ يَلْبَسَ ثَوْبًا مِنْ ‏ ‏فَيْءِ ‏ ‏الْمُسْلِمِينَ حَتَّى إِذَا ‏ ‏أَخْلَقَهُ ‏ ‏رَدَّهُ فِيهِ وَلَا يَرْكَبَ دَابَّةً مِنْ ‏ ‏فَيْءِ ‏ ‏الْمُسْلِمِينَ حَتَّى إِذَا ‏ ‏أَعْجَفَهَا ‏ ‏رَدَّهَا فِيهِ ‏","","",""],[16377,16377,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بَكْرُ بْنُ سَوَادَةَ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ نُعَيْمٍ ‏ ‏عَنْ ‏ ‏وَفَاءٍ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏رُوَيْفِعِ بْنِ ثَابِتٍ الْأَنْصَارِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَلَّى عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَقَالَ اللَّهُمَّ أَنْزِلْهُ الْمَقْعَدَ الْمُقَرَّبَ عِنْدَكَ يَوْمَ الْقِيَامَةِ وَجَبَتْ لَهُ شَفَاعَتِي ‏","","",""],[16378,16378,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏وَقُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏حَنَشٍ الصَّنْعَانِيِّ ‏ ‏عَنْ ‏ ‏رُوَيْفِعِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَحِلُّ لِأَحَدٍ ‏ ‏وَقَالَ ‏ ‏قُتَيْبَةُ ‏ ‏لِرَجُلٍ ‏ ‏أَنْ يَسْقِيَ مَاءَهُ وَلَدَ غَيْرِهِ وَلَا يَقَعُ عَلَى أَمَةٍ حَتَّى تَحِيضَ أَوْ يَبِينَ حَمْلُهَا ‏","","",""],[16379,16379,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏حَنَشٍ الصَّنْعَانِيِّ ‏ ‏عَنْ ‏ ‏رُوَيْفِعِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏تُوطَأَ ‏ ‏الْأَمَةُ حَتَّى تَحِيضَ وَعَنْ الْحَبَالَى حَتَّى يَضَعْنَ مَا فِي بُطُونِهِنَّ ‏","","",""],[16380,16380,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏مِنْ كِتَابِهِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عَيَّاشِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏شِيَيْمِ بْنِ بَيْتَانَ ‏ ‏عَنْ ‏ ‏أَبِي سَالِمٍ ‏ ‏عَنْ ‏ ‏شَيْبَانَ بْنِ أُمَيَّةَ ‏ ‏عَنْ ‏ ‏رُوَيْفِعِ بْنِ ثَابِتٍ الْأَنْصَارِيِّ ‏ ‏أَنَّهُ ‏ ‏غَزَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَكَانَ أَحَدُنَا يَأْخُذُ النَّاقَةَ عَلَى النِّصْفِ مِمَّا يَغْنَمُ حَتَّى أَنَّ لِأَحَدِنَا ‏ ‏الْقِدْحَ ‏ ‏وَلِلْآخَرِ ‏ ‏النَّصْلَ ‏ ‏وَالرِّيشَ ‏","","",""],[16381,16381,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاَقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عَيَّاشِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏شِيَيْمِ بْنِ بَيْتَانَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏مَسْلَمَةُ بْنُ مُخَلَّدٍ ‏ ‏عَلَى أَسْفَلِ الْأَرْضِ قَالَ فَاسْتَعْمَلَ ‏ ‏رُوَيْفِعَ بْنَ ثَابِتٍ الْأَنْصَارِيَّ ‏ ‏فَسِرْنَا مَعَهُ مِنْ ‏ ‏شَرِيكٍ ‏ ‏إِلَى ‏ ‏كَوْمِ عَلْقَامَ ‏ ‏أَوْ مِنْ ‏ ‏كَوْمِ عَلْقَامَ ‏ ‏إِلَى ‏ ‏شَرِيكٍ ‏ ‏قَالَ فَقَالَ ‏ ‏رُوَيْفِعُ بْنُ ثَابِتٍ ‏ ‏كُنَّا نَغْزُو عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَأْخُذُ أَحَدُنَا جَمَلَ أَخِيهِ عَلَى أَنَّ لَهُ النِّصْفَ مِمَّا يَغْنَمُ قَالَ حَتَّى أَنَّ أَحَدَنَا لَيَصِيرُ لَهُ ‏ ‏الْقِدْحُ ‏ ‏وَلِلْآخَرِ ‏ ‏النَّصْلُ ‏ ‏وَالرِّيشُ ‏ ‏قَالَ فَقَالَ ‏ ‏رُوَيْفِعُ بْنُ ثَابِتٍ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏رُوَيْفِعُ ‏ ‏لَعَلَّ الْحَيَاةَ سَتَطُولُ بِكَ فَأَخْبِرْ النَّاسَ أَنَّهُ ‏ ‏مَنْ عَقَدَ لِحْيَتَهُ أَوْ ‏ ‏تَقَلَّدَ ‏ ‏وَتَرًا ‏ ‏أَوْ ‏ ‏اسْتَنْجَى ‏ ‏بِرَجِيعِ ‏ ‏دَابَّةٍ أَوْ عَظْمٍ فَقَدْ بَرِئَ مِمَّا أَنْزَلَ اللَّهُ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[16382,16382,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى الْأَشْيَبُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَيَّاشُ بْنُ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏شِيَيْمِ بْنِ بَيْتَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏رُوَيْفِعُ بْنُ ثَابِتٍ ‏ ‏قَالَ ‏ ‏كَانَ أَحَدُنَا فِي زَمَانِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْخُذُ جَمَلَ أَخِيهِ عَلَى أَنْ يُعْطِيَهُ النِّصْفَ مِمَّا يَغْنَمُ وَلَهُ النِّصْفُ حَتَّى أَنَّ أَحَدَنَا لَيَطِيرُ لَهُ ‏ ‏النَّصْلُ ‏ ‏وَالرِّيشُ ‏ ‏وَالْآخَرَ ‏ ‏الْقِدْحُ ‏ ‏ثُمَّ قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏رُوَيْفِعُ ‏ ‏لَعَلَّ الْحَيَاةَ سَتَطُولُ بِكَ فَأَخْبِرْ النَّاسَ أَنَّهُ ‏ ‏مَنْ عَقَدَ لِحْيَتَهُ أَوْ ‏ ‏تَقَلَّدَ ‏ ‏وَتَرًا ‏ ‏أَوْ ‏ ‏اسْتَنْجَى ‏ ‏بِرَجِيعِ ‏ ‏دَابَّةٍ أَوْ عَظْمٍ فَإِنَّ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْهُ بَرِيءٌ ‏","","",""],[16383,16383,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي مَرْزُوقٍ ‏ ‏مَوْلَى ‏ ‏تُجِيبَ ‏ ‏عَنْ ‏ ‏حَنَشٍ الصَّنْعَانِيِّ ‏ ‏قَالَ ‏ ‏غَزَوْنَا مَعَ ‏ ‏رُوَيْفِعِ بْنِ ثَابِتٍ الْأَنْصَارِيِّ ‏ ‏قَرْيَةً مِنْ قُرَى ‏ ‏الْمَغْرِبِ ‏ ‏يُقَالُ لَهَا ‏ ‏جَرَبَّةُ ‏ ‏فَقَامَ فِينَا خَطِيبًا فَقَالَ أَيُّهَا النَّاسُ إِنِّي لَا أَقُولُ فِيكُمْ إِلَّا مَا سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ قَامَ فِينَا يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏فَقَالَ ‏ ‏لَا يَحِلُّ لِامْرِئٍ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ أَنْ يَسْقِيَ مَاءَهُ زَرْعَ غَيْرِهِ ‏ ‏يَعْنِي ‏ ‏إِتْيَانَ ‏ ‏الْحَبَالَى مِنْ ‏ ‏السَّبَايَا ‏ ‏وَأَنْ يُصِيبَ امْرَأَةً ‏ ‏ثَيِّبًا ‏ ‏مِنْ ‏ ‏السَّبْيِ ‏ ‏حَتَّى ‏ ‏يَسْتَبْرِئَهَا ‏ ‏يَعْنِي إِذَا اشْتَرَاهَا ‏ ‏وَأَنْ يَبِيعَ مَغْنَمًا ‏ ‏حَتَّى يُقْسَمَ وَأَنْ يَرْكَبَ دَابَّةً مِنْ ‏ ‏فَيْءِ ‏ ‏الْمُسْلِمِينَ حَتَّى إِذَا ‏ ‏أَعْجَفَهَا ‏ ‏رَدَّهَا فِيهِ وَأَنْ يَلْبَسَ ثَوْبًا مِنْ ‏ ‏فَيْءِ ‏ ‏الْمُسْلِمِينَ حَتَّى إِذَا ‏ ‏أَخْلَقَهُ ‏ ‏رَدَّهُ فِيهِ ‏","","",""],[16384,16384,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي جَعْفَرٍ الْمِصْرِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَنْ سَمِعَ ‏ ‏حَنَشَاً الصَّنْعَانِيَّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏رُوَيْفِعَ بْنَ ثَابِتٍ الْأَنْصَارِيَّ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا يَبْتَاعَنَّ ذَهَبًا بِذَهَبٍ إِلَّا وَزْنًا بِوَزْنٍ وَلَا يَنْكِحُ ‏ ‏ثَيِّبًا ‏ ‏مِنْ ‏ ‏السَّبْيِ ‏ ‏حَتَّى تَحِيضَ ‏","","",""],[16385,16385,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ يَزِيدَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏حَنَشٌ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ ‏ ‏رُوَيْفِعِ بْنِ ثَابِتٍ ‏ ‏غَزْوَةَ ‏ ‏جَرَبَّةَ ‏ ‏فَقَسَمَهَا عَلَيْنَا وَقَالَ لَنَا ‏ ‏رُوَيْفِعٌ ‏ ‏مَنْ ‏ ‏أَصَابَ ‏ ‏مِنْ هَذَا ‏ ‏السَّبْيِ ‏ ‏فَلَا ‏ ‏يَطَؤُهَا ‏ ‏حَتَّى تَحِيضَ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا ‏ ‏يَحِلُّ ‏ ‏لِرَجُلٍ أَنْ يَسْقِيَ مَاءَهُ وَلَدَ غَيْرِهِ ‏","","",""],[16386,16386,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُفَضَّلُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَيَّاشُ بْنُ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏شِيَيْمَ بْنَ بَيْتَانَ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏شَيْبَانَ الْقِتْبَانِيَّ ‏ ‏يَقُولُ ‏ ‏اسْتَخْلَفَ ‏ ‏مَسْلَمَةُ بْنُ مُخَلَّدٍ ‏ ‏رُوَيْفِعَ بْنَ ثَابِتٍ الْأَنْصَارِيَّ ‏ ‏عَلَى أَسْفَلِ الْأَرْضِ قَالَ فَسِرْنَا مَعَهُ قَالَ قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏رُوَيْفِعُ ‏ ‏لَعَلَّ الْحَيَاةَ سَتَطُولُ بِكَ بَعْدِي فَأَخْبِرْ النَّاسَ أَنَّهُ ‏ ‏مَنْ عَقَدَ لِحْيَتَهُ أَوْ ‏ ‏تَقَلَّدَ ‏ ‏وَتَرًا أَوْ اسْتَنْجَى ‏ ‏بِرَجِيعِ ‏ ‏دَابَّةٍ أَوْ بِعَظْمٍ فَإِنَّ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَرِيءٌ مِنْهُ ‏","","",""],[16387,16387,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي الْخَيْرِ ‏ ‏قَالَ ‏ ‏عَرَضَ ‏ ‏مَسْلَمَةُ بْنُ مُخَلَّدٍ ‏ ‏وَكَانَ أَمِيرًا عَلَى ‏ ‏مِصْرَ ‏ ‏عَلَى ‏ ‏رُوَيْفِعِ بْنِ ثَابِتٍ ‏ ‏أَنْ يُوَلِّيَهُ ‏ ‏الْعُشُورَ ‏ ‏فَقَالَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ صَاحِبَ ‏ ‏الْمَكْسِ ‏ ‏فِي النَّارِ ‏","","",""],[16388,16388,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَرِيزٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ عَامِرٍ الْأَلْهَانِيَّ ‏ ‏قَالَ ‏ ‏دَخَلَ الْمَسْجِدَ ‏ ‏حَابِسُ بْنُ سَعْدٍ الطَّائِيُّ ‏ ‏مِنْ ‏ ‏السَّحَرِ ‏ ‏وَقَدْ أَدْرَكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَأَى النَّاسَ يُصَلُّونَ فِي مُقَدَّمِ الْمَسْجِدِ فَقَالَ ‏ ‏مُرَاءُونَ ‏ ‏وَرَبِّ ‏ ‏الْكَعْبَةِ ‏ ‏أَرْعِبُوهُمْ فَمَنْ أَرْعَبَهُمْ فَقَدْ أَطَاعَ اللَّهَ وَرَسُولَهُ قَالَ فَأَتَاهُمْ النَّاسُ فَأَخْرَجُوهُمْ قَالَ فَقَالَ إِنَّ الْمَلَائِكَةَ تُصَلِّي مِنْ ‏ ‏السَّحَرِ ‏ ‏فِي مُقَدَّمِ الْمَسْجِدِ ‏","","",""],[16389,16389,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنِي ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ لَقِيطٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ حَوَالَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ نَجَا مِنْ ثَلَاثٍ فَقَدْ نَجَا ثَلَاثَ مَرَّاتٍ مَوْتِي ‏ ‏وَالدَّجَّالِ ‏ ‏وَقَتْلِ خَلِيفَةٍ مُصْطَبِرٍ بِالْحَقِّ مُعْطِيهِ ‏","","",""],[16390,16390,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنِ ‏ ‏ابْنِ حَوَالَةَ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ جَالِسٌ فِي ظِلِّ ‏ ‏دَوْمَةٍ ‏ ‏وَعِنْدَهُ كَاتِبٌ لَهُ ‏ ‏يُمْلِي عَلَيْهِ فَقَالَ أَلَا أَكْتُبُكَ يَا ‏ ‏ابْنَ حَوَالَةَ ‏ ‏قُلْتُ لَا أَدْرِي مَا ‏ ‏خَارَ ‏ ‏اللَّهُ لِي وَرَسُولُهُ فَأَعْرَضَ عَنِّي ‏ ‏وَقَالَ ‏ ‏إِسْمَاعِيلُ ‏ ‏مَرَّةً فِي الْأُولَى نَكْتُبُكَ يَا ‏ ‏ابْنَ حَوَالَةَ ‏ ‏قُلْتُ لَا أَدْرِي فِيمَ يَا رَسُولَ اللَّهِ فَأَعْرَضَ عَنِّي ‏ ‏فَأَكَبَّ ‏ ‏عَلَى كَاتِبِهِ ‏ ‏يُمْلِي عَلَيْهِ ثُمَّ قَالَ أَنَكْتُبُكَ يَا ‏ ‏ابْنَ حَوَالَةَ ‏ ‏قُلْتُ لَا أَدْرِي مَا ‏ ‏خَارَ ‏ ‏اللَّهُ لِي وَرَسُولُهُ فَأَعْرَضَ عَنِّي ‏ ‏فَأَكَبَّ ‏ ‏عَلَى كَاتِبِهِ ‏ ‏يُمْلِي عَلَيْهِ قَالَ فَنَظَرْتُ فَإِذَا فِي الْكِتَابِ ‏ ‏عُمَرُ ‏ ‏فَقُلْتُ إِنَّ ‏ ‏عُمَرَ ‏ ‏لَا يُكْتَبُ إِلَّا فِي خَيْرٍ ثُمَّ قَالَ أَنَكْتُبُكَ يَا ‏ ‏ابْنَ حَوَالَةَ ‏ ‏قُلْتُ نَعَمْ فَقَالَ يَا ‏ ‏ابْنَ حَوَالَةَ ‏ ‏كَيْفَ تَفْعَلُ فِي فِتْنَةٍ تَخْرُجُ فِي ‏ ‏أَطْرَافِ ‏ ‏الْأَرْضِ كَأَنَّهَا ‏ ‏صَيَاصِي ‏ ‏بَقَرٍ قُلْتُ لَا أَدْرِي مَا ‏ ‏خَارَ ‏ ‏اللَّهُ لِي وَرَسُولُهُ قَالَ وَكَيْفَ تَفْعَلُ فِي أُخْرَى تَخْرُجُ بَعْدَهَا كَأَنَّ الْأُولَى فِيهَا انْتِفَاجَةُ أَرْنَبٍ قُلْتُ لَا أَدْرِي مَا ‏ ‏خَارَ ‏ ‏اللَّهُ لِي وَرَسُولُهُ قَالَ ‏ ‏اتَّبِعُوا هَذَا قَالَ وَرَجُلٌ ‏ ‏مُقَفٍّ ‏ ‏حِينَئِذٍ قَالَ فَانْطَلَقْتُ فَسَعَيْتُ وَأَخَذْتُ بِمَنْكِبَيْهِ فَأَقْبَلْتُ بِوَجْهِهِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ هَذَا قَالَ نَعَمْ قَالَ وَإِذَا هُوَ ‏ ‏عُثْمَانُ بْنُ عَفَّانَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏","","",""],[16391,16391,"","","‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏وَيَزِيدُ بْنُ عَبْدِ رَبِّهِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بَحِيرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏أَبِي قُتَيْلَةَ ‏ ‏عَنِ ‏ ‏ابْنِ حَوَالَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَيَصِيرُ الْأَمْرُ إِلَى أَنْ تَكُونَ جُنُودٌ مُجَنَّدَةٌ جُنْدٌ ‏ ‏بِالشَّامِ ‏ ‏وَجُنْدٌ ‏ ‏بِالْيَمَنِ ‏ ‏وَجُنْدٌ ‏ ‏بِالْعِرَاقِ ‏ ‏فَقَالَ ‏ ‏ابْنُ حَوَالَةَ ‏ ‏خِرْ ‏ ‏لِي يَا رَسُولَ اللَّهِ إِنْ أَدْرَكْتُ ذَاكَ قَالَ ‏ ‏عَلَيْكَ ‏ ‏بِالشَّامِ ‏ ‏فَإِنَّهُ خِيرَةُ اللَّهِ مِنْ أَرْضِهِ ‏ ‏يَجْتَبِي ‏ ‏إِلَيْهِ خِيرَتَهُ مِنْ عِبَادِهِ فَإِنْ أَبَيْتُمْ فَعَلَيْكُمْ بِيَمَنِكُمْ وَاسْقُوا مِنْ غُدُرِكُمْ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ تَوَكَّلَ لِي ‏ ‏بِالشَّامِ ‏ ‏وَأَهْلِهِ ‏","","",""],[16392,16392,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنِي ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ لَقِيطٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ حَوَالَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ نَجَا مِنْ ثَلَاثٍ فَقَدْ نَجَا ثَلَاثَ مَرَّاتٍ مَوْتِي ‏ ‏وَالدَّجَّالِ ‏ ‏وَقَتْلِ خَلِيفَةٍ مُصْطَبِرٍ بِالْحَقِّ مُعْطِيهِ ‏","","",""],[16393,16393,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ الْقَيْسِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُمَيْدُ بْنُ هِلَالٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بَشْرُ بْنُ عَاصِمٍ اللَّيْثِيُّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ مَالِكٍ ‏ ‏وَكَانَ مِنْ رَهْطِهِ ‏ ‏قَالَ ‏ ‏بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَرِيَّةً ‏ ‏فَسَلَّحْتُ رَجُلًا سَيْفًا قَالَ فَلَمَّا رَجَعَ قَالَ مَا رَأَيْتُ مِثْلَ مَا لَامَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَعَجَزْتُمْ إِذْ بَعَثْتُ رَجُلًا فَلَمْ يَمْضِ لِأَمْرِي أَنْ تَجْعَلُوا مَكَانَهُ مَنْ ‏ ‏يَمْضِي لِأَمْرِي ‏","","",""],[16394,16394,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏بِشْرِ بْنِ عَاصِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُقْبَةُ بْنُ مَالِكٍ اللَّيْثِيُّ ‏ ‏قَالَ ‏ ‏بَيْنَمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ إِذْ قَالَ الْقَائِلُ يَا رَسُولَ اللَّهِ وَاللَّهِ مَا قَالَ الَّذِي قَالَ إِلَّا تَعَوُّذًا مِنْ الْقَتْلِ فَذَكَرَ قِصَّتَهُ فَأَقْبَلَ عَلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُعْرَفُ الْمَسَاءَةُ فِي وَجْهِهِ ثُمَّ قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ أَبَى عَلَيَّ مَنْ قَتَلَ مُؤْمِنًا قَالَهَا ثَلَاثَ مَرَّاتٍ ‏","","",""],[16395,16395,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏قَالَ ‏ ‏جَمَعَ بَيْنِي وَبَيْنَ ‏ ‏بِشْرِ بْنِ عَاصِمٍ ‏ ‏رَجُلٌ ‏ ‏فَحَدَّثَنِي عَنْ ‏ ‏عُقْبَةَ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏سَرِيَّةً ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَشُوا ‏ ‏أَهْلَ مَاءٍ صُبْحًا ‏ ‏فَبَرَزَ ‏ ‏رَجُلٌ مِنْ أَهْلِ الْمَاءِ فَحَمَلَ عَلَيْهِ رَجُلٌ مِنْ الْمُسْلِمِينَ فَقَالَ إِنِّي مُسْلِمٌ فَقَتَلَهُ فَلَمَّا قَدِمُوا أَخْبَرُوا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِذَلِكَ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطِيبًا فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ أَمَّا بَعْدُ ‏ ‏فَمَا بَالُ الْمُسْلِمِ يَقْتُلُ الرَّجُلَ وَهُوَ يَقُولُ إِنِّي مُسْلِمٌ فَقَالَ الرَّجُلُ إِنَّمَا قَالَهَا مُتَعَوِّذًا فَصَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجْهَهُ وَمَدَّ يَدَهُ الْيُمْنَى فَقَالَ أَبَى اللَّهُ عَلَيَّ مَنْ قَتَلَ مُسْلِمًا ثَلَاثَ مَرَّاتٍ ‏","","",""],[16396,16396,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ حِمْيَرٍ الْحِمْصِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ثَابِتُ بْنُ عَجْلَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا كَثِيرٍ الْمُحَارِبِيَّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏خَرَشَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏سَتَكُونُ مِنْ بَعْدِي ‏ ‏فِتْنَةٌ ‏ ‏النَّائِمُ فِيهَا خَيْرٌ مِنْ الْيَقْظَانِ وَالْقَاعِدُ فِيهَا خَيْرٌ مِنْ الْقَائِمِ وَالْقَائِمُ فِيهَا خَيْرٌ مِنْ ‏ ‏السَّاعِي ‏ ‏فَمَنْ أَتَتْ عَلَيْهِ فَلْيَمْشِ بِسَيْفِهِ إِلَى ‏ ‏صَفَاةٍ ‏ ‏فَلْيَضْرِبْهُ بِهَا حَتَّى يَنْكَسِرَ ثُمَّ لِيَضْجَعْ لَهَا حَتَّى ‏ ‏تَنْجَلِيَ ‏ ‏عَمَّا ‏ ‏انْجَلَتْ ‏","","",""],[16397,16397,"","","‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدُ بْنُ عَبْدِ الرَّحْمَنِ الرُّؤَاسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ عَبْدِ اللَّهِ الْأَوْدِيِّ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ الْحِمْيَرِيِّ ‏ ‏قَالَ ‏ ‏لَقِيتُ ‏ ‏رَجُلًا ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَحِبَهُ مِثْلَ مَا صَحِبَهُ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏فَمَا زَادَنِي عَلَى ثَلَاثِ كَلِمَاتٍ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَغْتَسِلُ الرَّجُلُ مِنْ ‏ ‏فَضْلِ ‏ ‏امْرَأَتِهِ وَلَا تَغْتَسِلُ ‏ ‏بِفَضْلِهِ ‏ ‏وَلَا يَبُولُ فِي ‏ ‏مُغْتَسَلِهِ وَلَا يَمْتَشِطُ فِي كُلِّ يَوْمٍ ‏","","",""],[16398,16398,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ عَبْدِ اللَّهِ الْأَوْدِيِّ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ الْحِمْيَرِيِّ ‏ ‏قَالَ ‏ ‏لَقِيتُ ‏ ‏رَجُلًا ‏ ‏قَدْ صَحِبَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَعَ سِنِينَ كَمَا صَحِبَهُ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏أَرْبَعَ سِنِينَ قَالَ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَمْتَشِطَ أَحَدُنَا كُلَّ يَوْمٍ وَأَنْ يَبُولَ فِي مُغْتَسَلِهِ وَأَنْ تَغْتَسِلَ الْمَرْأَةُ بِفَضْلِ الرَّجُلِ وَأَنْ يَغْتَسِلَ الرَّجُلُ بِفَضْلِ الْمَرْأَةِ وَلْيَغْتَرِفُوا جَمِيعًا ‏","","",""],[16399,16399,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ هُوَ ابْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ هُوُ ابْنُ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي حَبِيبَةَ ‏ ‏عَنْ ‏ ‏ذَلِكَ ‏ ‏الرَّجُلِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلِي حَاجَةٌ فَرَأَى عَلَيَّ ‏ ‏خَلُوقًا ‏ ‏فَقَالَ ‏ ‏اذْهَبْ فَاغْسِلْهُ فَغَسَلْتُهُ ثُمَّ عُدْتُ إِلَيْهِ فَقَالَ اذْهَبْ فَاغْسِلْهُ فَذَهَبْتُ فَوَقَعْتُ فِي بِئْرٍ فَأَخَذْتُ ‏ ‏مِشْقَةً ‏ ‏فَجَعَلْتُ أَتَتَبَّعُهُ ثُمَّ عُدْتُ إِلَيْهِ فَقَالَ حَاجَتُكَ ‏","","",""],[16400,16400,"","","‏ ‏حَدَّثَنَا ‏ ‏غُنْدَرٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شَدَّادُ بْنُ عَبْدِ اللَّهِ ‏ ‏وَكَانَ قَدْ أَدْرَكَ نَفَرًا مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبَسَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ عَلِّمْنِي مِمَّا عَلَّمَكَ اللَّهُ عَزَّ وَجَلَّ قَالَ ‏ ‏إِذَا صَلَّيْتَ الصُّبْحَ فَأَقْصِرْ عَنْ الصَّلَاةِ حَتَّى تَطْلُعَ الشَّمْسُ فَإِذَا طَلَعَتْ فَلَا تُصَلِّ حَتَّى تَرْتَفِعَ فَإِنَّهَا تَطْلُعُ حِينَ تَطْلُعُ بَيْنَ قَرْنَيْ شَيْطَانٍ وَحِينَئِذٍ يَسْجُدُ لَهَا الْكُفَّارُ فَإِذَا ارْتَفَعَتْ ‏ ‏قِيدَ ‏ ‏رُمْحٍ أَوْ رُمْحَيْنِ فَصَلِّ فَإِنَّ الصَّلَاةَ مَشْهُودَةٌ مَحْضُورَةٌ حَتَّى ‏ ‏يَعْنِي ‏ ‏يَسْتَقِلَّ ‏ ‏الرُّمْحُ بِالظِّلِّ ثُمَّ أَقْصِرْ عَنْ الصَّلَاةِ فَإِنَّهَا حِينَئِذٍ ‏ ‏تُسْجَرُ ‏ ‏جَهَنَّمُ فَإِذَا ‏ ‏أَفَاءَ ‏ ‏الْفَيْءُ ‏ ‏فَصَلِّ فَإِنَّ الصَّلَاةَ مَشْهُودَةٌ مَحْضُورَةٌ حَتَّى تُصَلِّيَ الْعَصْرَ فَإِذَا صَلَّيْتَ الْعَصْرَ فَأَقْصِرْ عَنْ الصَّلَاةِ حَتَّى تَغْرُبَ الشَّمْسُ فَإِنَّهَا تَغْرُبُ بَيْنَ قَرْنَيْ شَيْطَانٍ فَحِينَئِذٍ يَسْجُدُ لَهَا الْكُفَّارُ ‏","","",""]];
